function openTaskFromWorkload(projectId, taskId) {
  state.activeProjectId = projectId;
  state.teamWorkloadView = false;
  state.trainingLogView = false;
  state.projectsListView = false;
  state.projectTimelineView = false;
  state.openSlotsView = false;
  state.tiView = false;
  state.homeView = false;
  state.teamWorkloadView = false;
  state.trainingLogView = false;
  state.projectsListView = false;
  state.projectTimelineView = false;
  state.openSlotsView = false;
  state.tiView = false;
  saveState();
  render();
  setTimeout(() => {
    if (typeof openTaskModal === 'function') openTaskModal(null, taskId);
  }, 50);
}

// =============================================================
// CAPACITY & PTO MODAL
// =============================================================

let _tcmActiveTab = 'capacity';

function openTeamCapacityModal() {
  _tcmActiveTab = 'capacity';
  switchTcmTab('capacity');
  document.getElementById('teamCapacityModal').classList.add('active');
}

function switchTcmTab(tab) {
  _tcmActiveTab = tab;
  document.querySelectorAll('.tcm-tab-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.tab === tab);
  });
  document.getElementById('tcmTabCapacity').style.display = tab === 'capacity' ? 'block' : 'none';
  document.getElementById('tcmTabHolidays').style.display = tab === 'holidays' ? 'block' : 'none';
  if (tab === 'capacity') renderCapacityTab();
  else renderHolidaysTab();
}

function renderCapacityTab() {
  const list = document.getElementById('tcmCapList');
  if (!list) return;
  const members = state.teamMembers || [];
  if (members.length === 0) {
    list.innerHTML = '<div class="tcm-empty">No team members yet. Add team members via Manage Team in the sidebar first.</div>';
    return;
  }
  list.innerHTML = members.map(m => {
    const ptoSorted = (m.pto || []).slice().sort();
    return `
      <div class="tcm-cap-row" data-member-name="${escapeAttr(m.name)}">
        <div class="tcm-cap-row-header">
          <div class="tcm-cap-avatar" style="background:${avatarColor(m.name)};">${escapeHtml(m.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</div>
          <div class="tcm-cap-row-name">${escapeHtml(m.name)}</div>
          <div class="tcm-cap-row-cap">
            <label>Weekly capacity:</label>
            <input type="number" min="0" max="80" step="1" value="${m.capacityHrs || 0}" onchange="updateMemberCapacity('${escapeAttr(m.name)}', this.value)">
            <span>hrs</span>
          </div>
          <div class="tcm-cap-row-role">
            <label>Role:</label>
            <select onchange="updateMemberRole('${escapeAttr(m.name)}', this.value)">
              <option value="lead" ${m.role === 'lead' ? 'selected' : ''}>Lead only</option>
              <option value="support" ${m.role === 'support' ? 'selected' : ''}>Support only</option>
              <option value="both" ${m.role === 'both' || !m.role ? 'selected' : ''}>Lead + Support</option>
            </select>
          </div>
        </div>
        <div class="tcm-pto-section">
          <div class="tcm-pto-add-row">
            <label>Add PTO day:</label>
            <input type="date" id="tcmPtoDate-${escapeAttr(m.name)}">
            <button class="btn btn-sm" onclick="addMemberPto('${escapeAttr(m.name)}')">+ Add PTO</button>
          </div>
          ${ptoSorted.length === 0 ? '<div class="tcm-pto-empty">No PTO scheduled.</div>' : `
            <div class="tcm-pto-chips">
              ${ptoSorted.map(d => `
                <span class="tcm-pto-chip">${formatDate(d)}<button onclick="removeMemberPto('${escapeAttr(m.name)}', '${escapeAttr(d)}')" title="Remove PTO">×</button></span>
              `).join('')}
            </div>
          `}
        </div>
      </div>
    `;
  }).join('');
}

function updateMemberCapacity(name, val) {
  const m = (state.teamMembers || []).find(x => x.name === name);
  if (!m) return;
  const n = parseInt(val);
  m.capacityHrs = (isNaN(n) || n < 0) ? 0 : n;
  saveState();
}

function updateMemberRole(name, role) {
  const m = (state.teamMembers || []).find(x => x.name === name);
  if (!m) return;
  if (!['lead','support','both'].includes(role)) role = 'both';
  m.role = role;
  saveState();
}

function addMemberPto(name) {
  const m = (state.teamMembers || []).find(x => x.name === name);
  if (!m) return;
  const dateInput = document.getElementById(`tcmPtoDate-${name}`);
  if (!dateInput || !dateInput.value) {
    alert('Pick a date first.');
    return;
  }
  if (!Array.isArray(m.pto)) m.pto = [];
  if (!m.pto.includes(dateInput.value)) m.pto.push(dateInput.value);
  dateInput.value = '';
  saveState();
  renderCapacityTab();
}

function removeMemberPto(name, date) {
  const m = (state.teamMembers || []).find(x => x.name === name);
  if (!m || !Array.isArray(m.pto)) return;
  m.pto = m.pto.filter(d => d !== date);
  saveState();
  renderCapacityTab();
}

function renderHolidaysTab() {
  const list = document.getElementById('tcmHolidayList');
  if (!list) return;
  const holidays = (state.teamHolidays || []).slice().sort();
  if (holidays.length === 0) {
    list.innerHTML = '<div class="tcm-empty">No team holidays defined yet. Add one above.</div>';
    return;
  }
  list.innerHTML = holidays.map(d => `
    <div class="tcm-holiday-row">
      <span class="tcm-holiday-date">${formatDate(d)}</span>
      <button class="btn btn-sm" style="color:var(--red);" onclick="removeTeamHoliday('${escapeAttr(d)}')">× Remove</button>
    </div>
  `).join('');
}

function addTeamHoliday() {
  const dateInput = document.getElementById('tcmHolidayDate');
  if (!dateInput || !dateInput.value) {
    alert('Pick a date first.');
    return;
  }
  if (!Array.isArray(state.teamHolidays)) state.teamHolidays = [];
  if (!state.teamHolidays.includes(dateInput.value)) state.teamHolidays.push(dateInput.value);
  dateInput.value = '';
  document.getElementById('tcmHolidayName').value = '';
  saveState();
  renderHolidaysTab();
}

function removeTeamHoliday(date) {
  if (!Array.isArray(state.teamHolidays)) return;
  state.teamHolidays = state.teamHolidays.filter(d => d !== date);
  saveState();
  renderHolidaysTab();
}

// =============================================================
// REASSIGN TASKS MODAL
// =============================================================

let _reassignSelected = new Set();

function openReassignModal(sourceAssignee) {
  _reassignSelected = new Set();
  document.getElementById('reassignSourceAssignee').value = sourceAssignee;
  document.getElementById('reassignSearch').value = '';
  document.getElementById('reassignModalTitle').textContent = `Reassign Tasks from ${sourceAssignee}`;
  // Populate target dropdown with other team members
  const targetSel = document.getElementById('reassignTargetSelect');
  const others = (state.teamMembers || []).filter(m => m.name !== sourceAssignee);
  targetSel.innerHTML = '<option value="">— Select assignee —</option>' +
    others.map(m => `<option value="${escapeAttr(m.name)}">${escapeHtml(m.name)}</option>`).join('');
  renderReassignList();
  document.getElementById('reassignTasksModal').classList.add('active');
}

function _getReassignTaskList() {
  const sourceAssignee = document.getElementById('reassignSourceAssignee').value;
  const search = (document.getElementById('reassignSearch').value || '').trim().toLowerCase();
  const tasks = [];
  (state.projects || []).filter(p => !p.archived).forEach(project => {
    (project.tasks || []).forEach(task => {
      if (task.status === 'done') return;
      const isLead = (Array.isArray(task.leads) && task.leads.includes(sourceAssignee)) ||
                     task.assignee === sourceAssignee;
      const isSupport = (Array.isArray(task.supportMembers) && task.supportMembers.includes(sourceAssignee)) ||
                        task.support === sourceAssignee;
      if (!isLead && !isSupport) return;
      if (search) {
        const hay = (task.title + ' ' + project.name).toLowerCase();
        if (!hay.includes(search)) return;
      }
      tasks.push({
        taskId: task.id,
        projectId: project.id,
        projectName: project.name,
        title: task.title,
        dueDate: task.dueDate || '',
        critical: !!task.critical,
        estimatedHours: (typeof task.estimatedHours === 'number' && task.estimatedHours > 0) ? task.estimatedHours : 0,
        isLead, isSupport
      });
    });
  });
  // Sort: critical first, then by due date
  tasks.sort((a, b) => {
    if (a.critical !== b.critical) return a.critical ? -1 : 1;
    return (a.dueDate || '9999').localeCompare(b.dueDate || '9999');
  });
  return tasks;
}

function renderReassignList() {
  const listEl = document.getElementById('reassignList');
  if (!listEl) return;
  const tasks = _getReassignTaskList();
  if (tasks.length === 0) {
    listEl.innerHTML = '<div class="reassign-empty">No tasks match the current search.</div>';
    updateReassignSummary();
    return;
  }
  listEl.innerHTML = tasks.map(t => {
    const checked = _reassignSelected.has(t.taskId);
    return `
      <label class="reassign-row ${checked ? 'selected' : ''} ${t.critical ? 'is-critical' : ''}">
        <input type="checkbox" ${checked ? 'checked' : ''} onchange="toggleReassignTask('${escapeAttr(t.taskId)}', this.checked)">
        ${t.critical ? '<span class="reassign-crit">🔥</span>' : '<span class="reassign-crit"></span>'}
        <span class="reassign-title" title="${escapeAttr(t.title)}">${escapeHtml(t.title)}${_trainingChipMiniHtml(t)}</span>
        <span class="reassign-project">${escapeHtml(t.projectName)}</span>
        <span class="reassign-role">${t.isLead ? 'Lead' : 'Support'}</span>
        <span class="reassign-due">${t.dueDate ? formatDate(t.dueDate) : '—'}</span>
        <span class="reassign-hours">${t.estimatedHours > 0 ? t.estimatedHours + 'h' : '—'}</span>
      </label>
    `;
  }).join('');
  updateReassignSummary();
}

function toggleReassignTask(taskId, checked) {
  if (checked) _reassignSelected.add(taskId);
  else _reassignSelected.delete(taskId);
  renderReassignList();
}

function reassignSelectAll(select) {
  const tasks = _getReassignTaskList();
  tasks.forEach(t => {
    if (select) _reassignSelected.add(t.taskId);
    else _reassignSelected.delete(t.taskId);
  });
  renderReassignList();
}

function updateReassignSummary() {
  const count = _reassignSelected.size;
  const countEl = document.getElementById('reassignSelectedCount');
  const pluralEl = document.getElementById('reassignSelectedPlural');
  const applyBtn = document.getElementById('reassignApplyBtn');
  if (countEl) countEl.textContent = count;
  if (pluralEl) pluralEl.textContent = count === 1 ? '' : 's';
  if (applyBtn) {
    applyBtn.disabled = count === 0;
    applyBtn.textContent = count === 0 ? '↪ Reassign' : `↪ Reassign ${count}`;
  }
}

function applyReassignment() {
  const sourceAssignee = document.getElementById('reassignSourceAssignee').value;
  const targetSel = document.getElementById('reassignTargetSelect');
  const target = targetSel.value;
  if (!target) {
    alert('Pick a new assignee from the dropdown first.');
    return;
  }
  if (_reassignSelected.size === 0) {
    alert('Pick at least one task to reassign.');
    return;
  }
  if (!confirm(`Reassign ${_reassignSelected.size} task${_reassignSelected.size === 1 ? '' : 's'} from "${sourceAssignee}" to "${target}"?`)) return;

  let count = 0;
  (state.projects || []).forEach(project => {
    (project.tasks || []).forEach(task => {
      if (!_reassignSelected.has(task.id)) return;
      // Update lead chips
      if (Array.isArray(task.leads)) {
        const idx = task.leads.indexOf(sourceAssignee);
        if (idx !== -1) {
          task.leads[idx] = target;
          // Dedupe in case target was already a lead
          task.leads = Array.from(new Set(task.leads));
          task.assignee = task.leads[0] || '';
        }
      } else if (task.assignee === sourceAssignee) {
        task.assignee = target;
      }
      // Update support
      if (Array.isArray(task.supportMembers)) {
        const idx = task.supportMembers.indexOf(sourceAssignee);
        if (idx !== -1) {
          task.supportMembers[idx] = target;
          task.supportMembers = Array.from(new Set(task.supportMembers));
        }
      } else if (task.support === sourceAssignee) {
        task.support = target;
      }
      count++;
    });
  });
  saveState();
  closeModal('reassignTasksModal');
  renderTeamWorkloadView();
  setTimeout(() => alert(`✓ Reassigned ${count} task${count === 1 ? '' : 's'} to ${target}.`), 100);
}

// =============================================================
// STAND-UP SUMMARY — copy a markdown digest to clipboard
// =============================================================

function copyTeamStandupSummary() {
  const stats = _aggregateWorkloadByAssignee();
  const sorted = _sortWorkloadList(Array.from(stats.values()));
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  let lines = [];
  lines.push(`📋 SBG Precon Stand-up — ${today}`);
  lines.push('');
  sorted.forEach(s => {
    const projectCount = s.projectsLead.size + s.projectsSupport.size;
    lines.push(`👤 ${s.name} (${s.totalOpen} open · ${s.totalOpenHours}h · ${projectCount} project${projectCount === 1 ? '' : 's'})`);
    if (s.criticalCount > 0) lines.push(`   🔥 ${s.criticalCount} critical`);
    if (s.overdue > 0) lines.push(`   ⚠ ${s.overdue} overdue`);
    if (s.dueToday > 0) lines.push(`   📅 ${s.dueToday} due today`);
    if (s.dueTomorrow > 0) lines.push(`   📅 ${s.dueTomorrow} due tomorrow`);
    lines.push('');
  });
  const text = lines.join('\n');
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      alert('✓ Stand-up summary copied to clipboard. Paste into Slack/Teams/email.');
    }, () => {
      alert('Could not copy. Here\'s the summary:\n\n' + text);
    });
  } else {
    alert('Clipboard not supported. Here\'s the summary:\n\n' + text);
  }
}

function setSnapshotScope(scope) {
  if (!['all', 'active', 'mine'].includes(scope)) return;
  state.statusSnapshotScope = scope;
  saveState();
  renderStatusSnapshot();
}

function scrollToSnapshotSection(key) {
  const el = document.getElementById('ssvSection_' + key);
  if (el) {
    el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    // Brief highlight pulse so the eye lands on the right section
    el.classList.add('ssv-section-highlight');
    setTimeout(() => el.classList.remove('ssv-section-highlight'), 1800);
  }
}

function toggleSnapshotSection(key) {
  if (!state.statusSnapshotCollapsed) state.statusSnapshotCollapsed = {};
  state.statusSnapshotCollapsed[key] = !state.statusSnapshotCollapsed[key];
  saveState();
  const el = document.getElementById('ssvSection_' + key);
  if (el) el.classList.toggle('ssv-section-collapsed', !!state.statusSnapshotCollapsed[key]);
}

function resetSnapshotSectionOrder() {
  state.statusSnapshotSectionOrder = ['atrisk', 'inprogress', 'due1', 'due2', 'allopen'];
  saveState();
  renderStatusSnapshot();
}

// Returns the projects in scope based on the current scope filter.
// Always excludes archived projects from results.
function getSnapshotScopedProjects() {
  const scope = state.statusSnapshotScope || 'all';
  let projects = state.projects.filter(p => !p.archived);
  if (scope === 'active') {
    projects = projects.filter(p => p.id === state.activeProjectId);
  }
  return projects;
}

// Core data: collect tasks into the four buckets. Returns { atrisk: [], inprogress: [], due1: [], due2: [] }.
// Items in `bucket.items` shape: { project, task, dueLabel, urgencyMs, isOverdue }.
// Tasks can appear in multiple buckets (in-progress AND due-soon, e.g.) — by design.
function collectSnapshotBuckets() {
  const projects = getSnapshotScopedProjects();
  const scope = state.statusSnapshotScope || 'all';
  const user = getCurrentUser();
  const userLower = (user || '').toLowerCase();
  const filterToMine = scope === 'mine';

  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const day1End = new Date(todayStart.getTime() + 2 * 86400000);   // end of tomorrow
  const day2End = new Date(todayStart.getTime() + 3 * 86400000);   // end of day after tomorrow

  const buckets = { atrisk: [], inprogress: [], due1: [], due2: [], allopen: [] };

  projects.forEach(p => {
    (p.tasks || []).forEach(t => {
      // Skip done tasks from all buckets — they don't need attention
      if (t.status === 'done') return;
      // Mine-only filter
      if (filterToMine) {
        const isMine = (typeof isTaskMember === 'function')
          ? isTaskMember(t, userLower)
          : ((t.assignee && t.assignee.toLowerCase() === userLower) ||
             (t.support && t.support.toLowerCase() === userLower) ||
             (Array.isArray(t.supportMembers) && t.supportMembers.some(m => (m || '').toLowerCase() === userLower)));
        if (!isMine) return;
      }
      const due = t.dueDate ? new Date(t.dueDate + 'T23:59:59') : null;
      const urgencyMs = due ? (due.getTime() - now.getTime()) : Infinity;
      const isOverdue = due && due < now && !isSameDay(due, now);
      const isDueToday = due && isSameDay(due, todayStart);
      const isDueTomorrow = due && isSameDay(due, new Date(todayStart.getTime() + 86400000));
      const isDueIn2 = due && due >= new Date(todayStart.getTime() + 2 * 86400000) && due < day2End;

      const entry = { project: p, task: t, urgencyMs, isOverdue, due };

      // 0. All Open — every task that isn't done, regardless of urgency.
      // This is the "always visible" list so the page never reads as empty.
      buckets.allopen.push(entry);

      // 1. In Progress — any task with status === 'in-progress' regardless of due
      if (t.status === 'in-progress') {
        buckets.inprogress.push(entry);
      }
      // 2. Due Today / Tomorrow — open task due in next 24h-ish (today + tomorrow)
      if (due && (isOverdue || isDueToday || isDueTomorrow)) {
        buckets.due1.push(entry);
      }
      // 3. Due in 2 Days — open task due 24-48h out
      if (isDueIn2) {
        buckets.due2.push(entry);
      }
      // 4. At Risk — overdue OR due within 2 days AND status is not-started OR has open required items
      // Also includes Late Start tasks (Start By passed and still not started)
      // when the feature is enabled for the task's stage.
      const dueWithin2 = due && due < day2End;
      const isNotStarted = t.status === 'not-started';
      const readiness = (typeof getTaskReadiness === 'function') ? getTaskReadiness(t) : { isReady: true };
      const hasOpenRequired = !readiness.isReady;
      const isLateStart = (typeof isStartByEnabledForStage === 'function' && isStartByEnabledForStage(t.stage)
                           && typeof isTaskLateStart === 'function' && isTaskLateStart(t));
      if ((isOverdue) || (dueWithin2 && (isNotStarted || hasOpenRequired)) || isLateStart) {
        buckets.atrisk.push(entry);
      }
    });
  });

  // Sort each bucket — most urgent first (smallest urgencyMs / most negative for overdue)
  Object.keys(buckets).forEach(k => {
    buckets[k].sort((a, b) => a.urgencyMs - b.urgencyMs);
  });

  return buckets;
}

// Section metadata — keyed for the order array
const SNAPSHOT_SECTIONS = {
  atrisk: {
    title: '🔴 At Risk',
    description: 'Overdue, OR due within 2 days but not started / has unfinished required items',
    accentColor: 'var(--sbg-red)',
    accentBg: 'rgba(200,50,43,0.06)',
    cssClass: 'ssv-section-atrisk',
    emptyMsg: 'Nothing at risk — every soon-due task has been started and required items handled.'
  },
  inprogress: {
    title: '⚙️ In Progress Now',
    description: 'Tasks the team is actively working on right now',
    accentColor: '#1a9ec9',
    accentBg: 'rgba(26,158,201,0.06)',
    cssClass: 'ssv-section-inprogress',
    emptyMsg: 'No tasks are currently in progress in the selected scope.'
  },
  due1: {
    title: '📅 Due Today / Tomorrow',
    description: 'Open tasks due in the next 24 hours (overdue tasks also surface here)',
    accentColor: '#c07f00',
    accentBg: 'rgba(192,127,0,0.06)',
    cssClass: 'ssv-section-due1',
    emptyMsg: 'Nothing due in the next 24 hours.'
  },
  due2: {
    title: '📅 Due in 2 Days',
    description: 'Open tasks due 24–48 hours out',
    accentColor: '#6e4eb8',
    accentBg: 'rgba(110,78,184,0.06)',
    cssClass: 'ssv-section-due2',
    emptyMsg: 'Nothing due 24–48 hours out.'
  },
  allopen: {
    title: '📋 All Open Tasks',
    description: 'Every open task across the selected scope, sorted by due date',
    accentColor: 'var(--sbg-navy)',
    accentBg: 'rgba(10,37,64,0.05)',
    cssClass: 'ssv-section-allopen',
    emptyMsg: 'No open tasks in the selected scope.'
  }
};

function renderStatusSnapshot() {
  // Update active state of scope buttons
  document.querySelectorAll('.ssv-scope-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.scope === state.statusSnapshotScope);
  });

  const buckets = collectSnapshotBuckets();

  // Update headline stat numbers
  document.getElementById('ssvStatAtRisk').textContent = buckets.atrisk.length;
  document.getElementById('ssvStatInProgress').textContent = buckets.inprogress.length;
  document.getElementById('ssvStatDue1').textContent = buckets.due1.length;
  document.getElementById('ssvStatDue2').textContent = buckets.due2.length;
  const allOpenStatEl = document.getElementById('ssvStatAllOpen');
  if (allOpenStatEl) allOpenStatEl.textContent = buckets.allopen.length;

  // Scope meta — show how many projects are being scanned
  const projects = getSnapshotScopedProjects();
  const scopeMeta = document.getElementById('ssvScopeMeta');
  if (scopeMeta) {
    const scopeLabels = {
      all: `Scanning ${projects.length} active project${projects.length === 1 ? '' : 's'}`,
      active: state.activeProjectId ? `Scanning current project only` : 'No active project selected',
      mine: `${projects.length} project${projects.length === 1 ? '' : 's'} · ${getCurrentUser() || 'sign in to filter'}`
    };
    scopeMeta.textContent = scopeLabels[state.statusSnapshotScope] || '';
  }

  // Empty state — only show when there are literally zero open tasks.
  // The All Open section is the floor; if it's empty, everything else is empty.
  const container = document.getElementById('ssvSectionsContainer');
  const emptyEl = document.getElementById('ssvEmpty');
  if (buckets.allopen.length === 0) {
    container.innerHTML = '';
    if (emptyEl) emptyEl.style.display = '';
    updateSnapshotSidebarBadge(0);
    return;
  }
  if (emptyEl) emptyEl.style.display = 'none';

  // Render sections in user-defined order
  const order = state.statusSnapshotSectionOrder || ['atrisk', 'inprogress', 'due1', 'due2', 'allopen'];
  container.innerHTML = order.map(key => renderSnapshotSection(key, buckets[key])).join('');

  // Wire drag-and-drop on each section header
  attachSnapshotDragHandlers();

  // Sidebar badge — count of items needing attention (excludes All Open
  // since it includes everything; the badge should reflect *urgency* not volume).
  const attentionTotal = buckets.atrisk.length + buckets.inprogress.length + buckets.due1.length + buckets.due2.length;
  updateSnapshotSidebarBadge(attentionTotal);
}

function renderSnapshotSection(key, items) {
  const meta = SNAPSHOT_SECTIONS[key];
  if (!meta) return '';
  const collapsed = !!(state.statusSnapshotCollapsed && state.statusSnapshotCollapsed[key]);
  const collapsedClass = collapsed ? ' ssv-section-collapsed' : '';
  const count = items.length;

  // Body — list of rows, or empty state
  let bodyHtml;
  if (count === 0) {
    bodyHtml = `<div class="ssv-section-empty">✓ ${escapeHtml(meta.emptyMsg)}</div>`;
  } else {
    bodyHtml = items.map(entry => renderSnapshotRow(entry, key)).join('');
  }

  return `
    <section class="ssv-section ${meta.cssClass}${collapsedClass}" id="ssvSection_${key}" data-snapkey="${key}" style="--ssv-accent: ${meta.accentColor}; --ssv-accent-bg: ${meta.accentBg};">
      <div class="ssv-section-header">
        <span class="ssv-grip" data-snapkey="${key}" title="Drag to reorder this section">⋮⋮</span>
        <div class="ssv-section-titlewrap" onclick="toggleSnapshotSection('${key}')">
          <span class="ssv-section-title">${meta.title}</span>
          <span class="ssv-section-count">${count}</span>
          <span class="ssv-section-desc">${escapeHtml(meta.description)}</span>
        </div>
        <span class="ssv-section-toggle" onclick="toggleSnapshotSection('${key}')">▾</span>
      </div>
      <div class="ssv-section-body">
        ${bodyHtml}
      </div>
    </section>
  `;
}

function renderSnapshotRow(entry, sectionKey) {
  const { project, task: t, due, isOverdue } = entry;

  // Project chip (since this is cross-project)
  const initials = project.name.split(/\s+/).map(w => w[0]).join('').slice(0,2).toUpperCase();
  const projectThumb = project.image
    ? `<img src="${project.image}" alt="" class="ssv-row-project-thumb">`
    : `<span class="ssv-row-project-thumb ssv-row-project-thumb-text">${escapeHtml(initials)}</span>`;

  // Status pill
  const statusLabels = { 'not-started': 'Not Started', 'in-progress': 'In Progress', 'blocked': 'Blocked', 'pending': 'Pending', 'done': 'Done' };
  const statusPill = `<span class="ssv-row-status status-${t.status}">${statusLabels[t.status] || t.status}</span>`;

  // Due / countdown — humanized
  let dueText = '';
  let dueClass = '';
  if (due) {
    const diffMs = due.getTime() - Date.now();
    const diffMins = Math.round(diffMs / 60000);
    const diffHours = Math.round(diffMs / 3600000);
    const diffDays = Math.round(diffMs / 86400000);
    if (isOverdue) {
      const overdueDays = Math.abs(diffDays);
      dueText = `OVERDUE ${overdueDays}d`;
      dueClass = 'ssv-due-overdue';
    } else if (diffMs < 3600000) {
      dueText = `${Math.max(0, diffMins)}m left`;
      dueClass = 'ssv-due-critical';
    } else if (diffMs < 86400000) {
      dueText = `${diffHours}h left`;
      dueClass = 'ssv-due-imminent';
    } else if (diffMs < 2 * 86400000) {
      dueText = `1 day`;
      dueClass = 'ssv-due-warning';
    } else {
      dueText = `${diffDays}d`;
      dueClass = 'ssv-due-ok';
    }
  } else {
    dueText = 'No date';
    dueClass = 'ssv-due-none';
  }

  // Assignee avatar
  const assigneeName = t.assignee || 'Unassigned';
  const assigneeAvatar = (typeof renderAvatarHtml === 'function') ? renderAvatarHtml(assigneeName, 'sm') :
    `<span class="ssv-row-avatar">${escapeHtml(assigneeName.charAt(0).toUpperCase())}</span>`;

  // Subtask / deliverable / tip chips (mirror Look Ahead row)
  let chipsHtml = '';
  const clInfo = (typeof getChecklistChipLabel === 'function') ? getChecklistChipLabel(t) : null;
  if (clInfo && !clInfo.allDone) {
    if (clInfo.hasRequiredOpen) {
      chipsHtml += `<span class="ssv-chip ssv-chip-required" title="${clInfo.reqLeft} required subtask${clInfo.reqLeft === 1 ? '' : 's'} still open">☐ ${clInfo.reqLeft} REQ</span>`;
    } else {
      chipsHtml += `<span class="ssv-chip ssv-chip-cl">☐ ${clInfo.done}/${clInfo.total}</span>`;
    }
  }
  const dlvInfo = (typeof getDeliverableChipLabel === 'function') ? getDeliverableChipLabel(t) : null;
  if (dlvInfo && !dlvInfo.allDone) {
    if (dlvInfo.hasRequiredOpen) {
      chipsHtml += `<span class="ssv-chip ssv-chip-required-dlv" title="${dlvInfo.reqLeft} required deliverable${dlvInfo.reqLeft === 1 ? '' : 's'} still open">📦 ${dlvInfo.reqLeft} REQ</span>`;
    } else {
      chipsHtml += `<span class="ssv-chip ssv-chip-dlv">📦 ${dlvInfo.done}/${dlvInfo.total}</span>`;
    }
  }
  if (t.bestPractice && t.bestPractice.trim()) {
    chipsHtml += `<span class="ssv-chip ssv-chip-bp" title="Best-practice notes from Lead">💡 Tip</span>`;
  }

  // Cross-section overlap indicator
  let overlapHint = '';
  if (sectionKey === 'inprogress' && due && due < new Date(Date.now() + 2 * 86400000)) {
    overlapHint = `<span class="ssv-overlap-hint" title="Also due soon">also: due soon</span>`;
  } else if ((sectionKey === 'due1' || sectionKey === 'due2') && t.status === 'in-progress') {
    overlapHint = `<span class="ssv-overlap-hint" title="Also currently in progress">also: in progress</span>`;
  } else if (sectionKey === 'atrisk' && t.status === 'in-progress') {
    overlapHint = `<span class="ssv-overlap-hint" title="Currently in progress">in progress</span>`;
  }

  return `
    <div class="ssv-row" onclick="openTaskFromSnapshot('${project.id}', '${t.id}')">
      <div class="ssv-row-project" title="${escapeHtml(project.name)}">${projectThumb}<span class="ssv-row-project-name">${escapeHtml(project.name)}</span></div>
      <div class="ssv-row-main">
        <div class="ssv-row-title">${escapeHtml(t.title)}${_trainingChipMiniHtml(t)}${chipsHtml ? ' ' + chipsHtml : ''}${overlapHint}</div>
        <div class="ssv-row-meta">
          ${statusPill}
          <span class="ssv-row-assignee">${assigneeAvatar}<span class="ssv-row-assignee-name">${escapeHtml(assigneeName)}</span></span>
        </div>
      </div>
      <div class="ssv-row-due ${dueClass}">${dueText}</div>
    </div>
  `;
}

// Open a task from the snapshot — switches to the project AND opens the modal
function openTaskFromSnapshot(projectId, taskId) {
  const p = state.projects.find(x => x.id === projectId);
  if (!p) return;
  // Don't switch active project if already there; otherwise switch silently
  if (state.activeProjectId !== projectId) {
    state.activeProjectId = projectId;
  }
  // Stay in snapshot view, just open the task modal on top
  // Need to set activeStageId to 'all' so task is found in any view we land in
  saveState();
  openTaskModal(null, taskId);
}

// Drag-and-drop reordering of sections.
// Pattern: sections are NOT draggable by default. The grip handle (⋮⋮)
// listens for mousedown and flips `draggable=true` on its parent section,
// so dragstart only fires when the user grabs the grip — not when they
// click anywhere else inside the section. After dragend the flag flips
// back to false. This is the reliable cross-browser pattern; making the
// whole section draggable conflicts with click handlers on inner buttons
// and rows.
let _ssvDragKey = null;
function attachSnapshotDragHandlers() {
  document.querySelectorAll('.ssv-section').forEach(sec => {
    const grip = sec.querySelector('.ssv-grip');
    if (grip) {
      // Arm the section for dragging only when the grip is pressed
      grip.addEventListener('mousedown', () => { sec.setAttribute('draggable', 'true'); });
      grip.addEventListener('touchstart', () => { sec.setAttribute('draggable', 'true'); }, { passive: true });
    }

    sec.addEventListener('dragstart', (e) => {
      // Only respond if the section was armed (grip mousedown fired)
      if (sec.getAttribute('draggable') !== 'true') {
        e.preventDefault();
        return;
      }
      _ssvDragKey = sec.dataset.snapkey;
      sec.classList.add('ssv-dragging');
      try {
        e.dataTransfer.effectAllowed = 'move';
        // setData is required by Firefox to actually start the drag
        e.dataTransfer.setData('text/plain', _ssvDragKey);
      } catch(err) {}
    });

    sec.addEventListener('dragend', () => {
      sec.classList.remove('ssv-dragging');
      sec.setAttribute('draggable', 'false');
      document.querySelectorAll('.ssv-drop-target').forEach(el => el.classList.remove('ssv-drop-target'));
      _ssvDragKey = null;
    });

    sec.addEventListener('dragover', (e) => {
      if (!_ssvDragKey) return;
      e.preventDefault();
      try { e.dataTransfer.dropEffect = 'move'; } catch(err) {}
      if (sec.dataset.snapkey !== _ssvDragKey) {
        sec.classList.add('ssv-drop-target');
      }
    });

    sec.addEventListener('dragleave', (e) => {
      // Only remove if we're truly leaving the section (not just entering a child)
      if (!sec.contains(e.relatedTarget)) {
        sec.classList.remove('ssv-drop-target');
      }
    });

    sec.addEventListener('drop', (e) => {
      e.preventDefault();
      sec.classList.remove('ssv-drop-target');
      const dropKey = sec.dataset.snapkey;
      if (!_ssvDragKey || _ssvDragKey === dropKey) return;
      const order = [...(state.statusSnapshotSectionOrder || ['atrisk','inprogress','due1','due2','allopen'])];
      const fromIdx = order.indexOf(_ssvDragKey);
      const toIdx = order.indexOf(dropKey);
      if (fromIdx < 0 || toIdx < 0) return;
      order.splice(fromIdx, 1);
      order.splice(toIdx, 0, _ssvDragKey);
      state.statusSnapshotSectionOrder = order;
      saveState();
      renderStatusSnapshot();
    });
  });
}

// Update the sidebar badge with the current snapshot total
function updateSnapshotSidebarBadge(total) {
  const badge = document.getElementById('ssbBadge');
  const sub = document.getElementById('ssbSubCount');
  if (badge) {
    if (total > 0) {
      badge.textContent = total;
      badge.style.display = 'inline-flex';
    } else {
      badge.style.display = 'none';
    }
  }
  if (sub) {
    sub.textContent = total > 0 ? `${total} item${total === 1 ? '' : 's'} on watch` : 'In Progress · Due Soon · At Risk';
  }
}

// Lightweight unconditional badge refresh — called from main render() so the
// badge stays current even when the user isn't on the snapshot page.
function refreshSnapshotSidebarBadge() {
  // Save scope, force scope to 'all' for badge calc, then restore
  const realScope = state.statusSnapshotScope;
  state.statusSnapshotScope = 'all';
  const buckets = collectSnapshotBuckets();
  state.statusSnapshotScope = realScope;
  // Badge reflects items needing *attention* — not the full open list
  const total = buckets.atrisk.length + buckets.inprogress.length + buckets.due1.length + buckets.due2.length;
  updateSnapshotSidebarBadge(total);
}

// Core data aggregators — pull from all projects at once

function getAllActiveCountdowns() {
  // Returns array of { project, type: 'bid'|'tp', date, cd, urgency }
  // Sorted by urgency (past first, then soonest future)
  // Skips archived projects — they shouldn't show in the countdown roll-up.
  const out = [];
  (state.projects || []).forEach(p => {
    if (p.archived) return;
    // Main bid submission
    if (p.dueDate) {
      const cd = getBidCountdown(p);
      if (cd) out.push({ project: p, type: 'bid', cd });
    }
    // Trade Partner Bids milestone
    const tpInst = getTradePartnerMilestoneInstance(p);
    if (tpInst) {
      const cd = getMilestoneCountdown(tpInst);
      if (cd) out.push({ project: p, type: 'tp', cd, milestoneDate: tpInst.date });
    }
  });
  // Sort: critical first (past/imminent/warning), then chronological
  out.sort((a, b) => a.cd.totalMs - b.cd.totalMs);
  return out;
}

function getMyTasksAcrossProjects(user) {
  // Returns all open tasks where user is assignee or support, grouped into buckets by urgency
  if (!user) return { overdue: [], today: [], tomorrow: [], thisweek: [], later: [] };
  const userLower = user.toLowerCase();
  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const tomorrowStart = new Date(todayStart.getTime() + 86400000);
  const dayAfterTomorrow = new Date(todayStart.getTime() + 2 * 86400000);
  const weekEnd = new Date(todayStart.getTime() + 7 * 86400000);

  const buckets = { overdue: [], today: [], tomorrow: [], thisweek: [], later: [] };

  (state.projects || []).forEach(p => {
    if (p.archived) return; // exclude archived projects from cross-project task roll-ups
    (p.tasks || []).forEach(t => {
      if (t.status === 'done') return;
      const isMine = (typeof isTaskMember === 'function')
        ? isTaskMember(t, user)
        : ((t.assignee && t.assignee.toLowerCase() === userLower) || isTaskSupport(t, user));
      if (!isMine) return;
      if (!t.dueDate) { buckets.later.push({ project: p, task: t }); return; }
      const due = new Date(t.dueDate + 'T23:59:59');
      if (due < now && !isSameDay(due, now)) buckets.overdue.push({ project: p, task: t });
      else if (isSameDay(due, todayStart)) buckets.today.push({ project: p, task: t });
      else if (isSameDay(due, tomorrowStart)) buckets.tomorrow.push({ project: p, task: t });
      else if (due < weekEnd) buckets.thisweek.push({ project: p, task: t });
      else buckets.later.push({ project: p, task: t });
    });
  });
  // Sort each bucket by due date ascending
  Object.keys(buckets).forEach(k => {
    buckets[k].sort((a, b) => {
      const da = a.task.dueDate ? new Date(a.task.dueDate).getTime() : Infinity;
      const db = b.task.dueDate ? new Date(b.task.dueDate).getTime() : Infinity;
      return da - db;
    });
  });
  return buckets;
}

function isSameDay(d1, d2) {
  return d1.getFullYear() === d2.getFullYear()
      && d1.getMonth() === d2.getMonth()
      && d1.getDate() === d2.getDate();
}

function getMyUnackedTasksAcrossProjects(user) {
  if (!user) return [];
  const userLower = user.toLowerCase();
  const out = [];
  (state.projects || []).forEach(p => {
    if (p.archived) return; // exclude archived projects
    (p.tasks || []).forEach(t => {
      if (t.status === 'done') return;
      if (t.acknowledged) return;
      if (!t.assignee || t.assignee.toLowerCase() !== userLower) return;
      out.push({ project: p, task: t });
    });
  });
  return out;
}

// v113: Series-deduped count of unack'd tasks for a user. Each recurring
// series counts as ONE item regardless of how many pre-generated instances
// exist. Used by sidebar badge + section header count so users see a
// realistic "things to do" number, not a flooded 60+.
function getMyUnackedGroupCount(user) {
  const raw = getMyUnackedTasksAcrossProjects(user);
  const seenSeries = new Set();
  let count = 0;
  raw.forEach(({ task }) => {
    if (task.seriesId) {
      if (seenSeries.has(task.seriesId)) return;
      seenSeries.add(task.seriesId);
    }
    count++;
  });
  return count;
}

function getMyUnreadMessagesAcrossProjects(user) {
  if (!user) return [];
  const out = [];
  (state.projects || []).forEach(p => {
    if (p.archived) return; // exclude archived projects
    getUnreadMessagesForUser(p, user).forEach(m => {
      out.push({ project: p, message: m });
    });
  });
  // Newest first
  out.sort((a, b) => (b.message.createdAt || 0) - (a.message.createdAt || 0));
  return out;
}

function getMyPendingSignoffsAcrossProjects(user) {
  if (!user) return [];
  const userLower = user.toLowerCase();
  const out = [];
  (state.projects || []).forEach(p => {
    if (p.archived) return; // exclude archived projects
    const lead = (p.leadEstimator || '').trim().toLowerCase();
    if (lead !== userLower) return; // Only projects where I'm the Lead
    (p.tasks || []).forEach(t => {
      if (t.status === 'done' && !t.completionAcknowledged && !t.completionRejected) {
        out.push({ project: p, task: t });
      }
    });
  });
  return out;
}

function getMyPendingRejectionsAcrossProjects(user) {
  if (!user) return [];
  const userLower = user.toLowerCase();
  const out = [];
  (state.projects || []).forEach(p => {
    if (p.archived) return; // exclude archived projects
    (p.tasks || []).forEach(t => {
      if (!t.completionRejected) return;
      if (t.completionRejectionAcknowledged) return;
      const isMine = (typeof isTaskMember === 'function')
        ? isTaskMember(t, user)
        : ((t.assignee && t.assignee.toLowerCase() === userLower) || isTaskSupport(t, user));
      if (!isMine) return;
      out.push({ project: p, task: t });
    });
  });
  return out;
}

// Count for sidebar badge — total actionable items for current user across all projects
function getHomeBadgeCount() {
  const user = getCurrentUser();
  if (!user) return 0;
  let count = 0;
  (state.projects || []).forEach(p => {
    if (p.archived) return; // exclude archived from badge
    count += getUnreadMessagesForUser(p, user).length;
    count += getUnseenReceiptsForSender(p, user).length;
  });
  count += getMyUnackedGroupCount(user);
  count += getMyPendingSignoffsAcrossProjects(user).length;
  count += getMyPendingRejectionsAcrossProjects(user).length;
  // Overdue tasks assigned to me
  const taskBuckets = getMyTasksAcrossProjects(user);
  count += taskBuckets.overdue.length + taskBuckets.today.length;
  return count;
}

function renderHomeSidebarBtn() {
  const btn = document.getElementById('homeSidebarBtn');
  const badge = document.getElementById('hsbBadge');
  const subCount = document.getElementById('hsbSubCount');
  if (!btn || !badge || !subCount) return;
  btn.classList.toggle('active', !!state.homeView);
  const count = getHomeBadgeCount();
  if (count > 0) {
    badge.textContent = count;
    badge.style.display = 'inline-flex';
    subCount.textContent = `${count} item${count === 1 ? '' : 's'} for you`;
  } else {
    badge.style.display = 'none';
    const user = getCurrentUser();
    subCount.textContent = user ? 'All caught up' : 'Sign in to see';
  }
  // Status Snapshot button — active state mirroring
  const snapBtn = document.getElementById('snapshotSidebarBtn');
  if (snapBtn) snapBtn.classList.toggle('active', !!state.statusSnapshotView);
}

function renderHomeView() {
  const user = getCurrentUser();
  const now = new Date();
  const greeting = (() => {
    const h = now.getHours();
    if (h < 12) return 'Good morning';
    if (h < 17) return 'Good afternoon';
    return 'Good evening';
  })();

  const greetEl = document.getElementById('homeGreeting');
  if (greetEl) {
    greetEl.textContent = user ? `${greeting}, ${user.split(/\s+/)[0]}` : 'Today';
  }
  const subEl = document.getElementById('homeSubtitle');
  if (subEl) {
    subEl.textContent = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  }

  // Show sign-in prompt and hide sections if no user
  const signinPrompt = document.getElementById('homeSigninPrompt');
  // v96: include the new My Workload section in show/hide handling
  const sections = ['homeMyWorkloadSection', 'homeMyTasksSection', 'homeUnackSection', 'homeMessagesSection'];
  if (!user) {
    if (signinPrompt) signinPrompt.style.display = 'block';
    sections.forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = 'none';
    });
    document.getElementById('homeSignoffsSection').style.display = 'none';
    document.getElementById('homeRejectionsSection').style.display = 'none';
  } else {
    if (signinPrompt) signinPrompt.style.display = 'none';
    sections.forEach(id => {
      const el = document.getElementById(id);
      if (el) el.style.display = 'block';
    });
  }

  // ---- Bid Countdowns (always visible regardless of sign-in)
  renderHomeCountdowns();

  // ---- Home stats
  renderHomeStats(user);

  if (!user) {
    // Still apply the persisted collapse state on the countdowns/messages
    // sections even when not signed in.
    _applyHomeCollapseState();
    _refreshCollapseAllBtn();
    return;
  }

  // v96: user-scoped sections. Rendered in the NEW ORDER matching the DOM:
  // My Workload → My Tasks → Awaiting Ack → Countdowns (rendered above)
  // → Required Items → Messages → Sign-Offs → Rejections.

  // ---- My Workload (v96 — user's snapshot from the workload aggregator)
  renderHomeMyWorkload(user);

  // ---- My Tasks
  renderHomeMyTasks(user);

  // ---- My Unacknowledged Tasks
  renderHomeUnack(user);

  // ---- My Required Items (cross-project) — top-of-mind unfinished
  renderHomeRequiredItems();

  // ---- My Unread Messages
  renderHomeMessages(user);

  // ---- My Sign-Offs (Lead only)
  renderHomeSignoffs(user);

  // ---- My Pending Rejections
  renderHomeRejections(user);

  // v96: apply persisted collapse state now that all sections have rendered
  _applyHomeCollapseState();
  _refreshCollapseAllBtn();
}

// =============================================================
// v96: Today page — collapse/expand section infrastructure
// =============================================================

// Toggle a single Today section. Persists state.homeCollapse[sectionId].
function toggleHomeSection(sectionId) {
  const el = document.getElementById(sectionId);
  if (!el) return;
  if (!state.homeCollapse) state.homeCollapse = {};
  const nowCollapsed = !el.classList.contains('home-section-collapsed');
  el.classList.toggle('home-section-collapsed', nowCollapsed);
  state.homeCollapse[sectionId] = nowCollapsed;
  saveState();
  _refreshCollapseAllBtn();
}

// Apply persisted collapse state to every home section on the page.
// Called after render() so DOM exists.
function _applyHomeCollapseState() {
  const collapseMap = (state.homeCollapse && typeof state.homeCollapse === 'object') ? state.homeCollapse : {};
  document.querySelectorAll('#homeView .home-section').forEach(section => {
    const id = section.id;
    if (!id) return;
    const shouldCollapse = !!collapseMap[id];
    section.classList.toggle('home-section-collapsed', shouldCollapse);
  });
}

// Toggle all sections at once. If any are currently expanded, collapse all;
// if all are already collapsed, expand all.
function toggleAllHomeSections() {
  const sections = Array.from(document.querySelectorAll('#homeView .home-section'))
    .filter(s => s.style.display !== 'none');
  if (sections.length === 0) return;
  const anyExpanded = sections.some(s => !s.classList.contains('home-section-collapsed'));
  const targetCollapsed = anyExpanded; // if any expanded, we're collapsing everything
  if (!state.homeCollapse) state.homeCollapse = {};
  sections.forEach(s => {
    if (!s.id) return;
    s.classList.toggle('home-section-collapsed', targetCollapsed);
    state.homeCollapse[s.id] = targetCollapsed;
  });
  saveState();
  _refreshCollapseAllBtn();
}

// Update the master collapse-all button label based on current state.
function _refreshCollapseAllBtn() {
  const btn = document.getElementById('homeCollapseAllBtn');
  if (!btn) return;
  const sections = Array.from(document.querySelectorAll('#homeView .home-section'))
    .filter(s => s.style.display !== 'none');
  if (sections.length === 0) { btn.textContent = '⇕ Expand All'; return; }
  const anyExpanded = sections.some(s => !s.classList.contains('home-section-collapsed'));
  btn.textContent = anyExpanded ? '⇱ Collapse All' : '⇲ Expand All';
  btn.title = anyExpanded
    ? 'Collapse every section on the Today page'
    : 'Expand every section on the Today page';
}

// =============================================================
// v96/v97: Today page — My Workload section renderer
// Full replica of the Team Workload page, filtered to the signed-in
// user only. Uses the same aggregator (_aggregateWorkloadByAssignee)
// and the same card renderer (_buildEstimatorCardHtml) as the Team
// Workload page so behavior is identical — capacity bar, per-day
// strip, top projects, PTO/holiday markers, open slots badge, and
// Reassign button all work here exactly like they do on the full
// team page. Toolbar controls (scope, grain, mode) share state with
// the Team Workload page so a change in either view flows to both.
// Skipped intentionally: Detail Table, 14-Day Look-Ahead chart, and
// Unassigned Pile — not useful for a single-user view.
// =============================================================
function renderHomeMyWorkload(user) {
  const section = document.getElementById('homeMyWorkloadSection');
  const body = document.getElementById('homeMyWorkloadBody');
  const sub = document.getElementById('homeMyWorkloadSub');
  if (!section || !body) return;
  if (!user) { section.style.display = 'none'; return; }
  section.style.display = 'block';

  // v97: Sync toolbar buttons to state so the active pill matches what's
  // selected. Uses the same class names as the Team Workload toolbar
  // (.twv-seg-btn, .twv-grain-btn, .twv-mode-btn) so the setter functions
  // update both toolbars in one query.
  const activeScope = state.workloadDateScope || 'two-week';
  const activeGrain = state.workloadGrain === 'week' ? 'week' : 'day';
  const activeMode = state.workloadMode === 'planned' ? 'planned' : 'current';
  section.querySelectorAll('.twv-seg-btn[data-scope]').forEach(b => {
    b.classList.toggle('active', b.dataset.scope === activeScope);
  });
  section.querySelectorAll('.twv-grain-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.grain === activeGrain);
  });
  section.querySelectorAll('.twv-mode-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.mode === activeMode);
  });

  // Aggregate workload for current user only
  let stats;
  try {
    const all = _aggregateWorkloadByAssignee();
    stats = all.get(user) || null;
  } catch (err) {
    body.innerHTML = '<div class="hmw-empty">Unable to compute workload. Refresh the page to retry.</div>';
    return;
  }

  // Handle "no tasks" state — user isn't in the aggregator map because they
  // have no assigned work. We still want to give them a friendly empty state
  // instead of a blank card.
  if (!stats) {
    if (sub) sub.textContent = 'Nothing on your plate right now';
    body.innerHTML = `
      <div class="hmw-empty">
        No open tasks assigned to you across any project. 🎉
      </div>
    `;
    return;
  }

  // Sub-headline in the section header — quick summary line
  const projectCount = stats.projectsLead.size + stats.projectsSupport.size;
  if (sub) {
    sub.textContent = `${stats.totalOpen} open · ${Math.round(stats.totalOpenHours * 10) / 10}h total · ${projectCount} project${projectCount === 1 ? '' : 's'}`;
  }

  // v97: render the standard estimator card. This gives us capacity bar,
  // stats row, top-5 projects list, per-day strip chart, PTO/holiday
  // markers, open slots badge, and Reassign button — all identical to the
  // Team Workload page. The card CSS has no fixed width so it stretches to
  // fill the section body (per the .hmw-card-wrap .twv-card { width:100% }
  // override in the stylesheet).
  try {
    body.innerHTML = _buildEstimatorCardHtml(stats);
  } catch (err) {
    body.innerHTML = '<div class="hmw-empty">Unable to render workload card. Refresh the page to retry.</div>';
  }
}

function renderHomeStats(user) {
  const el = document.getElementById('homeStats');
  if (!el) return;
  const allProjects = state.projects || [];
  const activeProjects = allProjects.filter(p => !p.dueDate || getDaysLeft(p.dueDate) >= 0);
  const countdowns = getAllActiveCountdowns();
  const critical = countdowns.filter(c => !c.cd.isPast && c.cd.totalMs < 24 * 3600000).length;
  const thisWeek = countdowns.filter(c => !c.cd.isPast && c.cd.totalMs < 7 * 86400000).length;

  const stats = [];
  stats.push(`<div class="home-stat is-info"><span class="hs-label">Active Pursuits</span><span class="hs-value">${activeProjects.length}</span></div>`);
  if (critical > 0) {
    stats.push(`<div class="home-stat is-critical"><span class="hs-label">Due &lt; 24h</span><span class="hs-value">${critical}</span></div>`);
  }
  if (thisWeek > 0) {
    stats.push(`<div class="home-stat is-warning"><span class="hs-label">Due This Week</span><span class="hs-value">${thisWeek}</span></div>`);
  }
  if (user) {
    const buckets = getMyTasksAcrossProjects(user);
    const myOverdue = buckets.overdue.length;
    const myToday = buckets.today.length;
    const myUnread = getMyUnreadMessagesAcrossProjects(user).length;
    const myUnack = getMyUnackedGroupCount(user);
    if (myOverdue > 0) stats.push(`<div class="home-stat is-critical"><span class="hs-label">My Overdue</span><span class="hs-value">${myOverdue}</span></div>`);
    if (myToday > 0) stats.push(`<div class="home-stat is-warning"><span class="hs-label">My Today</span><span class="hs-value">${myToday}</span></div>`);
    if (myUnack > 0) stats.push(`<div class="home-stat is-critical"><span class="hs-label">Unacknowledged</span><span class="hs-value">${myUnack}</span></div>`);
    if (myUnread > 0) stats.push(`<div class="home-stat is-info"><span class="hs-label">Unread Msgs</span><span class="hs-value">${myUnread}</span></div>`);
  }
  el.innerHTML = stats.join('');
}

function renderHomeCountdowns() {
  const list = document.getElementById('homeCountdownsList');
  const subEl = document.getElementById('homeCountdownsSub');
  if (!list) return;
  const countdowns = getAllActiveCountdowns();
  if (subEl) subEl.textContent = countdowns.length === 0 ? 'No active bids' : `${countdowns.length} countdown${countdowns.length === 1 ? '' : 's'}`;
  if (countdowns.length === 0) {
    list.innerHTML = '<div class="home-empty">No active bid deadlines configured.</div>';
    return;
  }
  list.innerHTML = countdowns.map(item => {
    const p = item.project;
    const cd = item.cd;
    const initials = p.name.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();
    const thumb = p.image
      ? `<div class="hcc-thumb"><img src="${p.image}" alt=""></div>`
      : `<div class="hcc-thumb">${escapeHtml(initials)}</div>`;
    let urgency = '';
    let countdownText = '';
    if (cd.isPast) {
      urgency = 'cd-past';
      countdownText = `PAST · ${cd.days}d ago`;
    } else if (cd.totalMs < 3600000) {
      urgency = 'cd-critical';
      countdownText = `${cd.minutes}m ${cd.seconds}s`;
    } else if (cd.totalMs < 2 * 3600000) {
      urgency = 'cd-critical';
      countdownText = `${cd.hours}h ${cd.minutes}m`;
    } else if (cd.totalMs < 24 * 3600000) {
      urgency = 'cd-imminent';
      countdownText = `${cd.hours}h ${cd.minutes}m`;
    } else if (cd.totalMs < 2 * 86400000) {
      urgency = 'cd-warning';
      countdownText = `${cd.days}d ${cd.hours}h`;
    } else if (cd.totalMs < 5 * 86400000) {
      urgency = 'cd-attention';
      countdownText = `${cd.days}d ${cd.hours}h`;
    } else {
      countdownText = `${cd.days}d`;
    }
    const typeLabel = item.type === 'tp' ? '💼 Trade Partner Bids' : '📤 Bid Submission';
    const dueLabel = item.type === 'tp' ? formatDate(item.milestoneDate) : formatDate(p.dueDate);
    return `
      <div class="home-countdown-card ${urgency}" onclick="jumpToProjectFromHome('${p.id}')">
        ${thumb}
        <div class="hcc-body">
          <div class="hcc-project">${escapeHtml(p.name)}</div>
          <div class="hcc-meta">${typeLabel} · ${dueLabel}</div>
        </div>
        <div class="hcc-right">
          <div class="hcc-countdown">${countdownText}</div>
          <div class="hcc-label">${cd.isPast ? 'past due' : 'remaining'}</div>
        </div>
      </div>
    `;
  }).join('');
}

// v132: Toggle the alert class on a Today-page section based on whether
// it has pending items. Pulses a red dot, tints the header, and shows a
// red left border animation so the whole thing catches the eye — even
// when the section is collapsed. Used by every render function on the
// Today page that surfaces action-worthy items.
function _setSectionAlertState(sectionId, hasAlerts) {
  const el = document.getElementById(sectionId);
  if (!el) return;
  el.classList.toggle('home-section-has-alerts', !!hasAlerts);
}

function renderHomeMyTasks(user) {
  const el = document.getElementById('homeMyTasksBuckets');
  const subEl = document.getElementById('homeMyTasksSub');
  if (!el) return;
  const buckets = getMyTasksAcrossProjects(user);
  const total = buckets.overdue.length + buckets.today.length + buckets.tomorrow.length + buckets.thisweek.length;
  if (subEl) subEl.textContent = total === 0 ? 'Nothing urgent this week' : `${total} open task${total === 1 ? '' : 's'} this week`;
  _setSectionAlertState('homeMyTasksSection', total > 0);

  if (total === 0) {
    el.innerHTML = '<div class="home-empty">✓ You have no open tasks due this week. Nice.</div>';
    return;
  }

  const bucketConfigs = [
    { key: 'overdue', label: 'Overdue', cls: 'bucket-overdue' },
    { key: 'today', label: 'Due Today', cls: 'bucket-today' },
    { key: 'tomorrow', label: 'Due Tomorrow', cls: 'bucket-tomorrow' },
    { key: 'thisweek', label: 'This Week', cls: 'bucket-thisweek' }
  ];

  const html = bucketConfigs
    .filter(cfg => buckets[cfg.key].length > 0)
    .map(cfg => {
      const items = buckets[cfg.key].map(({ project, task }) => renderHomeTaskItem(project, task, cfg.key)).join('');
      return `
        <div class="home-task-bucket ${cfg.cls}">
          <div class="home-task-bucket-label">${cfg.label} (${buckets[cfg.key].length})</div>
          ${items}
        </div>
      `;
    }).join('');
  el.innerHTML = html;
}

function renderHomeTaskItem(project, task, bucketKey) {
  const stage = STAGES.find(s => s.id === task.stage) || STAGES[0];
  const dueBadge = bucketKey === 'overdue'
    ? `<span class="hi-due-badge overdue">${task.dueDate ? 'OVERDUE' : 'OVERDUE'}</span>`
    : bucketKey === 'today'
      ? `<span class="hi-due-badge today">TODAY</span>`
      : bucketKey === 'tomorrow'
        ? `<span class="hi-due-badge tomorrow">TOMORROW</span>`
        : `<span class="hi-due-badge thisweek">${task.dueDate ? formatDateShort(task.dueDate) : 'SOON'}</span>`;
  const cls = bucketKey === 'overdue' ? 'hi-critical' : (bucketKey === 'today' ? 'hi-warning' : 'hi-info');
  return `
    <div class="home-item ${cls}" onclick="jumpToTaskFromHome('${project.id}', '${task.id}')">
      <span class="hi-project-chip" title="${escapeHtml(project.name)}">${escapeHtml(project.name)}</span>
      <div class="hi-body">
        <div class="hi-title">${escapeHtml(task.title)}${_trainingChipMiniHtml(task)}</div>
        <div class="hi-meta">${stage.icon} ${escapeHtml(stage.name)}</div>
      </div>
      <div class="hi-right">${dueBadge}</div>
    </div>
  `;
}

function renderHomeUnack(user) {
  const el = document.getElementById('homeUnackList');
  const subEl = document.getElementById('homeUnackSub');
  if (!el) return;
  const items = getMyUnackedTasksAcrossProjects(user);

  // v113: Collapse series into a single row per seriesId. When a user
  // creates a weekly recurring task, 8+ pre-generated instances all show
  // as separate ack items — floods the list even though acking one acks
  // all (v112 propagation). Group first, then render one row per series
  // with a badge showing how many occurrences the ack will cover.
  const grouped = [];       // ordered list of { kind, project, task, seriesCount? }
  const seenSeries = new Set();
  items.forEach(({ project, task }) => {
    if (task.seriesId) {
      if (seenSeries.has(task.seriesId)) return; // already represented
      seenSeries.add(task.seriesId);
      const seriesMembers = items.filter(it =>
        it.project.id === project.id && it.task.seriesId === task.seriesId
      );
      // Pick the earliest-dated instance as the visible row so the series
      // shows the soonest due date (most actionable).
      const earliest = seriesMembers
        .slice()
        .sort((a, b) => (a.task.dueDate || '9999').localeCompare(b.task.dueDate || '9999'))[0];
      grouped.push({
        kind: 'series',
        project: earliest.project,
        task: earliest.task,
        seriesCount: seriesMembers.length
      });
    } else {
      grouped.push({ kind: 'single', project, task });
    }
  });

  const groupedCount = grouped.length;
  const rawCount = items.length;
  const countLabel = groupedCount === rawCount
    ? `${groupedCount} task${groupedCount === 1 ? '' : 's'}`
    : `${groupedCount} item${groupedCount === 1 ? '' : 's'} (covers ${rawCount} instance${rawCount === 1 ? '' : 's'})`;
  if (subEl) subEl.textContent = groupedCount === 0 ? 'All acknowledged' : countLabel;
  _setSectionAlertState('homeUnackSection', groupedCount > 0);

  if (groupedCount === 0) {
    el.innerHTML = '<div class="home-empty">✓ No new tasks awaiting acknowledgment.</div>';
    return;
  }

  const btnAll = groupedCount > 1
    ? `<div style="margin-bottom:8px;"><button class="btn btn-primary btn-sm" onclick="acknowledgeAllMyTasksFromHome()">✓ Acknowledge All (${groupedCount})</button></div>`
    : '';

  el.innerHTML = btnAll + grouped.map(entry => {
    const { project, task, kind, seriesCount } = entry;
    const stage = STAGES.find(s => s.id === task.stage) || STAGES[0];
    const seriesBadge = (kind === 'series' && seriesCount > 1)
      ? `<span class="hi-series-badge" title="This is a recurring series — one acknowledgement covers all ${seriesCount} occurrences">🔁 ${seriesCount} occurrences</span>`
      : '';
    const cadence = (kind === 'series' && task.recurrence && typeof _formatRecurrenceCadence === 'function')
      ? ` · ${escapeHtml(_formatRecurrenceCadence(task.recurrence))}`
      : '';
    return `
      <div class="home-item hi-critical" onclick="jumpToTaskFromHome('${project.id}', '${task.id}')">
        <span class="hi-project-chip" title="${escapeHtml(project.name)}">${escapeHtml(project.name)}</span>
        <div class="hi-body">
          <div class="hi-title">${escapeHtml(task.title)}${_trainingChipMiniHtml(task)} ${seriesBadge}</div>
          <div class="hi-meta">${stage.icon} ${escapeHtml(stage.name)}${task.dueDate ? ' · Next due ' + formatDateShort(task.dueDate) : ''}${cadence}</div>
        </div>
        <button class="btn btn-primary btn-sm" onclick="event.stopPropagation(); acknowledgeTaskFromHome('${project.id}', '${task.id}');">✓ Acknowledge${kind === 'series' && seriesCount > 1 ? ' Series' : ''}</button>
      </div>
    `;
  }).join('');
}

function renderHomeMessages(user) {
  const el = document.getElementById('homeMessagesList');
  const subEl = document.getElementById('homeMessagesSub');
  if (!el) return;
  const items = getMyUnreadMessagesAcrossProjects(user);
  if (subEl) subEl.textContent = items.length === 0 ? 'No unread messages' : `${items.length} unread message${items.length === 1 ? '' : 's'}`;
  _setSectionAlertState('homeMessagesSection', items.length > 0);

  if (items.length === 0) {
    el.innerHTML = '<div class="home-empty">✓ No unread messages.</div>';
    return;
  }

  el.innerHTML = items.slice(0, 10).map(({ project, message }) => {
    const timeStr = message.createdAt
      ? new Date(message.createdAt).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })
      : '';
    const preview = (message.body || '').split('\n')[0].slice(0, 100);
    return `
      <div class="home-item hi-info" onclick="jumpToMessageFromHome('${project.id}')">
        <span class="hi-project-chip" title="${escapeHtml(project.name)}">${escapeHtml(project.name)}</span>
        <div class="hi-body">
          <div class="hi-title">From ${escapeHtml(message.from)}: ${escapeHtml(preview)}${message.body && message.body.length > 100 ? '…' : ''}</div>
          <div class="hi-meta">${timeStr}</div>
        </div>
      </div>
    `;
  }).join('') + (items.length > 10 ? `<div class="home-empty" style="text-align:left;padding:8px 12px;">+ ${items.length - 10} more — open a project to see all</div>` : '');
}

