// ----- Project-level events -----

function logProjectEdited(project, oldSnapshot) {
  if (!project || !oldSnapshot) return;
  const changes = [];
  const fieldsToCompare = [
    { key: 'name', label: 'Project Name' },
    { key: 'client', label: 'Owner' },
    { key: 'dueDate', label: 'Bid Due Date' },
    { key: 'startDate', label: 'Start Date' },
    { key: 'leadEstimator', label: 'Lead Estimator' },
    { key: 'status', label: 'Status' },
    { key: 'location', label: 'Location' },
    { key: 'architect', label: 'Architect' }
  ];
  fieldsToCompare.forEach(({ key, label }) => {
    const oldVal = oldSnapshot[key] || '';
    const newVal = project[key] || '';
    if (oldVal !== newVal) {
      changes.push({ field: label, from: oldVal, to: newVal });
    }
  });
  if (changes.length === 0) return;

  const summary = changes.length === 1
    ? `Edited project: ${changes[0].field} changed`
    : `Edited project: ${changes.length} fields changed`;

  logActivity(project, {
    type: 'project',
    action: 'edited',
    changes: changes,
    summary: summary
  });
}

