function loadTemplate() {
  const project = state.projects.find(p=>p.id===state.activeProjectId);
  if (!project) return;
  if (!Array.isArray(state.taskTemplates) || state.taskTemplates.length === 0) {
    alert('No templates defined. Open "Manage Task Templates" to create one first.');
    return;
  }

  // Always open the picker even with one template — the picker now has
  // both "Load All" and "Pick Tasks…" buttons on each card, so the user
  // needs to see it to access the selective-load flow. Previously this
  // fast-path skipped the picker for single-template setups, which hid
  // the Pick Tasks option from most users.
  openTemplatePicker(project);
}

// Show a picker letting the user choose which template to load into the project
function openTemplatePicker(project) {
  const list = document.getElementById('tmplPickerList');
  if (!list) return;
  // Build template cards
  list.innerHTML = state.taskTemplates.map(t => {
    const taskCount = (t.tasks || []).length;
    const stageBreakdown = {};
    (t.tasks || []).forEach(task => {
      stageBreakdown[task.stage] = (stageBreakdown[task.stage] || 0) + 1;
    });
    const stageChips = Object.entries(stageBreakdown).slice(0, 5).map(([stageId, count]) => {
      const stage = STAGES.find(s => s.id === stageId);
      const label = stage ? stage.name : stageId;
      return `<span class="tmpl-picker-stage-chip">${count} ${escapeHtml(label)}</span>`;
    }).join('');
    return `
      <div class="tmpl-picker-card${t.isDefault ? ' is-default' : ''}">
        <div class="tmpl-picker-card-header" style="background:${t.color || '#0a2540'};">
          <span class="tmpl-picker-icon">${(typeof renderTemplateIconHtml === 'function') ? renderTemplateIconHtml(t.icon) : escapeHtml(t.icon || '📋')}</span>
          <span class="tmpl-picker-name">${escapeHtml(t.name)}</span>
          ${t.isDefault ? '<span class="tmpl-picker-default-badge">★ DEFAULT</span>' : ''}
        </div>
        <div class="tmpl-picker-card-body">
          ${t.description ? `<p class="tmpl-picker-desc">${escapeHtml(t.description)}</p>` : ''}
          <div class="tmpl-picker-count"><strong>${taskCount}</strong> task${taskCount === 1 ? '' : 's'}</div>
          <div class="tmpl-picker-stages">${stageChips}${Object.keys(stageBreakdown).length > 5 ? `<span class="tmpl-picker-stage-chip">+${Object.keys(stageBreakdown).length - 5} more</span>` : ''}</div>
          <!-- Two-path action row v49: Load All for fast full-load, Pick Tasks for selective load -->
          <div class="tmpl-picker-actions">
            <button class="btn btn-primary btn-sm tmpl-picker-load-all" onclick="confirmApplyTemplate('${t.id}')" title="Load all tasks from this template into the project">📥 Load All</button>
            <button class="btn btn-sm tmpl-picker-pick" onclick="openTaskPickerForTemplate('${t.id}')" title="Choose specific tasks to load instead of the whole template">✓ Pick Tasks…</button>
          </div>
        </div>
      </div>
    `;
  }).join('');
  document.getElementById('tmplPickerModal').classList.add('active');
}

function confirmApplyTemplate(templateId) {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) return;
  const tmpl = state.taskTemplates.find(t => t.id === templateId);
  if (!tmpl) return;
  closeModal('tmplPickerModal');
  applyTemplateToProject(project, tmpl);
}

// =============================================================
// TASK PICKER (v49) — selective load: choose specific tasks from a template.
// Opens after the user clicks "Pick Tasks…" on a template card. All tasks
// default UNCHECKED so the user explicitly opts in. State held in a
// module-level Set keyed by the template's task index.
// =============================================================

// The set of task indices currently checked (in the active picker template)
let _taskPickerSelected = new Set();

function openTaskPickerForTemplate(templateId) {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) return;
  const tmpl = state.taskTemplates.find(t => t.id === templateId);
  if (!tmpl || !Array.isArray(tmpl.tasks) || tmpl.tasks.length === 0) {
    alert(`Template "${tmpl?.name || 'unknown'}" has no tasks to pick from.`);
    return;
  }
  // Close the template picker, open the task picker
  closeModal('tmplPickerModal');
  // Reset state — fresh selection set, blank search, all-stages filter
  _taskPickerSelected = new Set();
  document.getElementById('taskPickerTemplateId').value = templateId;
  document.getElementById('taskPickerSearch').value = '';
  // Populate stage filter dropdown with stages used by this template
  const stageFilter = document.getElementById('taskPickerStageFilter');
  const usedStageIds = new Set();
  tmpl.tasks.forEach(t => { if (t.stage) usedStageIds.add(t.stage); });
  const stageOpts = ['<option value="all">All Stages</option>'];
  STAGES.forEach(s => {
    if (usedStageIds.has(s.id)) {
      stageOpts.push(`<option value="${s.id}">${s.icon} ${escapeHtml(s.name)}</option>`);
    }
  });
  stageFilter.innerHTML = stageOpts.join('');
  stageFilter.value = 'all';
  // Update title with template name
  document.getElementById('taskPickerTitle').innerHTML = `Pick Tasks from <span style="color:var(--sbg-navy);">${escapeHtml(tmpl.name)}</span>`;
  renderTaskPickerList();
  document.getElementById('taskPickerModal').classList.add('active');
}

// Returns the task list filtered by current search + stage filter, with
// the original index attached so we can reference back to the template.
function _taskPickerGetFilteredTasks() {
  const templateId = document.getElementById('taskPickerTemplateId').value;
  const tmpl = state.taskTemplates.find(t => t.id === templateId);
  if (!tmpl) return [];
  const searchEl = document.getElementById('taskPickerSearch');
  const stageEl = document.getElementById('taskPickerStageFilter');
  const search = (searchEl ? searchEl.value.trim().toLowerCase() : '');
  const stageFilter = (stageEl ? stageEl.value : 'all');
  return tmpl.tasks
    .map((t, i) => ({ ...t, _index: i }))
    .filter(t => {
      if (stageFilter !== 'all' && t.stage !== stageFilter) return false;
      if (search && !(t.title || '').toLowerCase().includes(search)) return false;
      return true;
    });
}

// Render the task list grouped by stage with checkboxes.
function renderTaskPickerList() {
  const listEl = document.getElementById('taskPickerList');
  if (!listEl) return;
  const filtered = _taskPickerGetFilteredTasks();
  if (filtered.length === 0) {
    listEl.innerHTML = '<div class="task-picker-empty">No tasks match the current search or stage filter.</div>';
    updateTaskPickerSummary();
    return;
  }
  // Group by stage in the order STAGES are defined
  const byStage = {};
  filtered.forEach(t => {
    const sid = t.stage || '__nostage__';
    if (!byStage[sid]) byStage[sid] = [];
    byStage[sid].push(t);
  });
  // Build HTML — STAGES order, then any orphan stages at the end
  const orderedStageIds = STAGES.map(s => s.id).filter(id => byStage[id]);
  const orphanStageIds = Object.keys(byStage).filter(id => !STAGES.some(s => s.id === id));
  const allStageIds = [...orderedStageIds, ...orphanStageIds];
  let html = '';
  allStageIds.forEach(stageId => {
    const stage = STAGES.find(s => s.id === stageId);
    const stageName = stage ? stage.name : (stageId === '__nostage__' ? '(No stage)' : stageId);
    const stageIcon = stage ? (stage.icon || '🎯') : '📋';
    const tasks = byStage[stageId];
    // Stage header checkbox state — checked if all tasks in this stage are selected
    const allChecked = tasks.every(t => _taskPickerSelected.has(t._index));
    const someChecked = tasks.some(t => _taskPickerSelected.has(t._index));
    const indeterminate = someChecked && !allChecked;
    html += `
      <div class="task-picker-stage-group">
        <label class="task-picker-stage-header" onclick="event.stopPropagation();">
          <input type="checkbox" ${allChecked ? 'checked' : ''} ${indeterminate ? 'data-indeterminate="true"' : ''} onchange="mttToggleStageSelection('${escapeAttr(stageId)}', this.checked)">
          <span>${stageIcon} ${escapeHtml(stageName)}</span>
          <span class="task-picker-stage-count">${tasks.filter(t => _taskPickerSelected.has(t._index)).length}/${tasks.length}</span>
        </label>
        ${tasks.map(t => {
          const checked = _taskPickerSelected.has(t._index);
          const hours = (typeof t.estimatedHours === 'number' && t.estimatedHours > 0) ? `${t.estimatedHours}h` : '—';
          const offset = (typeof t.offset === 'number') ? `D${t.offset === 0 ? ' 0' : (t.offset > 0 ? '+' + t.offset : t.offset)}` : '—';
          const critical = !!t.critical;
          return `
            <label class="task-picker-task-row ${checked ? 'selected' : ''} ${critical ? 'is-critical' : ''}">
              <input type="checkbox" ${checked ? 'checked' : ''} onchange="mttToggleTaskSelection(${t._index}, this.checked)">
              <span class="task-picker-task-critical">${critical ? '🔥' : ''}</span>
              <span class="task-picker-task-title" title="${escapeAttr(t.title)}">${escapeHtml(t.title)}</span>
              <span class="task-picker-task-hours" title="Estimated hours">${hours}</span>
              <span class="task-picker-task-offset" title="Days from Bid Start">${offset}</span>
            </label>
          `;
        }).join('')}
      </div>
    `;
  });
  listEl.innerHTML = html;
  // Set indeterminate state on stage checkboxes that have partial selection
  // (HTML attr can't represent indeterminate; must set via JS property)
  listEl.querySelectorAll('input[data-indeterminate="true"]').forEach(cb => {
    cb.indeterminate = true;
  });
  updateTaskPickerSummary();
}

// Picker-specific toggle functions — prefixed `mtt` to avoid collision with
// the project-level bulk-selection toggleTaskSelection() defined elsewhere.
function mttToggleTaskSelection(index, checked) {
  if (checked) {
    _taskPickerSelected.add(index);
  } else {
    _taskPickerSelected.delete(index);
  }
  renderTaskPickerList();
}

function mttToggleStageSelection(stageId, checked) {
  // Toggle all currently-visible (filtered) tasks in this stage
  const filtered = _taskPickerGetFilteredTasks().filter(t => (t.stage || '__nostage__') === stageId);
  filtered.forEach(t => {
    if (checked) _taskPickerSelected.add(t._index);
    else _taskPickerSelected.delete(t._index);
  });
  renderTaskPickerList();
}

// Bulk select all currently-filtered tasks (or unselect them).
function taskPickerSelectAll(select) {
  const filtered = _taskPickerGetFilteredTasks();
  filtered.forEach(t => {
    if (select) _taskPickerSelected.add(t._index);
    else _taskPickerSelected.delete(t._index);
  });
  renderTaskPickerList();
}

// Update the live count + total hours in the footer + apply button enabled state.
function updateTaskPickerSummary() {
  const templateId = document.getElementById('taskPickerTemplateId').value;
  const tmpl = state.taskTemplates.find(t => t.id === templateId);
  if (!tmpl) return;
  const selectedTasks = Array.from(_taskPickerSelected)
    .map(i => tmpl.tasks[i])
    .filter(t => t);
  const count = selectedTasks.length;
  const totalHours = selectedTasks.reduce((sum, t) => sum + (typeof t.estimatedHours === 'number' && t.estimatedHours > 0 ? t.estimatedHours : 0), 0);
  const countEl = document.getElementById('taskPickerSelectedCount');
  const pluralEl = document.getElementById('taskPickerSelectedPlural');
  const hoursEl = document.getElementById('taskPickerSelectedHours');
  const applyBtn = document.getElementById('taskPickerApplyBtn');
  if (countEl) countEl.textContent = count;
  if (pluralEl) pluralEl.textContent = count === 1 ? '' : 's';
  if (hoursEl) hoursEl.textContent = totalHours > 0 ? `${totalHours} hrs` : '0 hrs';
  if (applyBtn) {
    applyBtn.disabled = count === 0;
    applyBtn.textContent = count === 0 ? '📥 Add Selected Tasks' : `📥 Add ${count} Selected Task${count === 1 ? '' : 's'}`;
  }
}

// Commit the picker — adds the selected template tasks to the active project.
function applySelectedTemplateTasks() {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) return;
  const templateId = document.getElementById('taskPickerTemplateId').value;
  const tmpl = state.taskTemplates.find(t => t.id === templateId);
  if (!tmpl) return;
  if (_taskPickerSelected.size === 0) {
    alert('No tasks selected. Check the boxes for tasks you want to add, or click Cancel.');
    return;
  }
  // Build the list of selected template tasks (preserves template's natural order)
  const selectedTasks = [];
  tmpl.tasks.forEach((t, i) => {
    if (_taskPickerSelected.has(i)) selectedTasks.push(t);
  });
  // Prep date warning if no anchor dates set
  if (!project.startDate && !project.dueDate) {
    if (!confirm(`No Bid Start or Due Date set. ${selectedTasks.length} task(s) from "${tmpl.name}" will be added without dates. Continue?`)) return;
  } else if (!confirm(`Add ${selectedTasks.length} task(s) from "${tmpl.name}" to this project? Day-offsets will be anchored to the Bid Start Date.`)) return;
  // Apply via the shared helper, then close + render
  const addedCount = _addTemplateTasksToProject(project, selectedTasks, tmpl.name);
  saveState();
  closeModal('taskPickerModal');
  render();
  setTimeout(() => alert(`✓ Added ${addedCount} task${addedCount === 1 ? '' : 's'} from "${tmpl.name}".`), 100);
}

function applyTemplateToProject(project, tmpl) {
  if (!tmpl || !Array.isArray(tmpl.tasks) || tmpl.tasks.length === 0) {
    alert(`Template "${tmpl?.name || 'unknown'}" has no tasks.`);
    return;
  }
  if (!project.startDate && !project.dueDate) {
    if (!confirm(`No Bid Start or Due Date set. ${tmpl.tasks.length} tasks from "${tmpl.name}" will be added without dates. Continue?`)) return;
  } else if (!confirm(`Load "${tmpl.name}" template (${tmpl.tasks.length} tasks) with day-offsets from the Bid Start Date?`)) return;

  // Reuse the shared helper that does the actual task creation. This keeps
  // the full-load and partial-load (Pick Tasks) paths in sync — any change
  // to the task-creation logic only needs to happen in one place.
  const addedCount = _addTemplateTasksToProject(project, tmpl.tasks, tmpl.name);
  saveState();
  render();
  setTimeout(() => alert(`✓ Loaded ${addedCount} tasks from "${tmpl.name}".`), 100);
}

// Shared helper — creates project tasks from a list of template tasks. Used
// by both the full-load path (applyTemplateToProject) and the partial-load
// path (applySelectedTemplateTasks). Does NOT call saveState/render — caller
// is responsible so it can batch operations and show its own confirmation.
// Returns the count of tasks added.
function _addTemplateTasksToProject(project, templateTasks, tmplName) {
  if (!Array.isArray(templateTasks) || templateTasks.length === 0) return 0;
  // v60: pre-flight — count tasks that require unfilled roles so we can
  // prompt the user to fill them BEFORE the templates load. The prompt
  // captures any newly-assigned people right back into the project.
  if (typeof _checkRolesBeforeTemplateLoad === 'function') {
    _checkRolesBeforeTemplateLoad(project, templateTasks);
  }
  let count = 0;
  templateTasks.forEach(x => {
    // v63 / v82+: Compute due date using per-task anchor. Four valid values:
    // 'bid-start' (project.startDate), 'bid-day' (project.dueDate),
    // 'pre-bid' (project.prebidDate), 'rfi-due' (project.rfiDueDate).
    // If the relevant anchor isn't set on the project, dueDate stays empty.
    const validAnchors = ['bid-start','bid-day','pre-bid','rfi-due'];
    const anchor = validAnchors.includes(x.dateAnchor) ? x.dateAnchor : 'bid-start';
    let anchorDate = '';
    if (anchor === 'bid-day')      anchorDate = (project.dueDate || '').trim();
    else if (anchor === 'pre-bid') anchorDate = (project.prebidDate || '').trim();
    else if (anchor === 'rfi-due') anchorDate = (project.rfiDueDate || '').trim();
    else                            anchorDate = (project.startDate || '').trim();
    // v63b: coerce offset to a number; missing/invalid → 0 (= due on anchor date).
    // Per user spec: 0 offset means the task is due ON the anchor date.
    const xOffset = (typeof x.offset === 'number' && !isNaN(x.offset)) ? x.offset : 0;
    const dueDate = anchorDate ? addBusinessDays(anchorDate, xOffset).date : '';
    // v60: build the leads array based on what roles the template marks
    // as required AND what people the project has in those role slots.
    // Senior Estimator → leadEstimator field. Lead 1 / Lead 2 → leadAssignee1/2.
    // Empty role slots are silently skipped (the project-setup prompt should
    // have caught them, but we handle it gracefully even if user dismissed).
    // v61: requiresSenior must be EXPLICITLY true to auto-assign — defaults
    // to false now (user opts in per task).
    const autoLeads = [];
    if (x.requiresSenior === true) {
      const sr = (project.leadEstimator || '').trim();
      if (sr) autoLeads.push(sr);
    }
    if (x.requiresLead1) {
      const l1 = (project.leadAssignee1 || '').trim();
      if (l1 && !autoLeads.includes(l1)) autoLeads.push(l1);
    }
    if (x.requiresLead2) {
      const l2 = (project.leadAssignee2 || '').trim();
      if (l2 && !autoLeads.includes(l2)) autoLeads.push(l2);
    }
    // Build the new project task, copying rich fields from the template.
    // Critical + estimatedHours + tips + deliverables + checklist all carry
    // through; deliverables and checklist are deep-cloned so editing the
    // project task doesn't mutate the template.
    const newTask = {
      id: uid(), title: x.title, stage: x.stage, category: x.category,
      priority: x.priority, status: 'not-started',
      dueDate, dayOffset: xOffset,
      // v63: persist the per-task date anchor so subsequent reanchor passes
      // (e.g., user shifts Bid Start or Bid Day) honor the original choice.
      dateAnchor: anchor,
      // v60: assignee mirrors first auto-lead (legacy compat for code that
      // reads task.assignee directly). leads array carries the full list.
      assignee: autoLeads[0] || '',
      leads: autoLeads.slice(),
      support: '', supportMembers: [], ballInCourt: 'Lead',
      source: x.source || '',
      notes: '', createdAt: Date.now(),
      critical: !!x.critical,
      estimatedHours: (typeof x.estimatedHours === 'number' && x.estimatedHours > 0) ? x.estimatedHours : null,
      bestPracticeNotes: (x.tips || '').trim() || ''
    };
    if (Array.isArray(x.deliverables) && x.deliverables.length > 0) {
      newTask.deliverables = x.deliverables.map(d => ({
        id: uid(),
        text: (typeof d === 'string') ? d : (d.text || ''),
        completed: false
      })).filter(d => d.text);
    }
    if (Array.isArray(x.checklist) && x.checklist.length > 0) {
      newTask.checklist = x.checklist.map(c => {
        if (typeof c === 'string') return { id: uid(), text: c, required: false, completed: false };
        return { id: uid(), text: c.text || '', required: !!c.required, completed: false };
      }).filter(c => c.text);
    }
    project.tasks.push(newTask);
    count++;
  });
  return count;
}

// =============================================================
// PROJECT ROLE HELPERS (v60)
// Three project-level role slots — Senior Estimator (leadEstimator),
// Lead Assignee 1 (leadAssignee1), and Lead Assignee 2 (leadAssignee2).
// Template tasks can declare which roles they require; the auto-load
// pulls the matching people into task.leads.
// =============================================================

// Inspect the about-to-be-loaded template tasks for any role requirements
// the project hasn't filled. If any are unfilled, prompt the user to fill
// them now — the prompt writes directly back to project.leadEstimator /
// leadAssignee1 / leadAssignee2 BEFORE _addTemplateTasksToProject reads them.
function _checkRolesBeforeTemplateLoad(project, templateTasks) {
  if (!project || !Array.isArray(templateTasks)) return;
  // Tally how many tasks need each role
  const need = { senior: 0, lead1: 0, lead2: 0 };
  templateTasks.forEach(t => {
    if (t.requiresSenior === true) need.senior++;
    if (t.requiresLead1) need.lead1++;
    if (t.requiresLead2) need.lead2++;
  });
  // Identify which slots are empty AND have tasks needing them
  const unfilled = [];
  if (need.senior > 0 && !(project.leadEstimator || '').trim()) unfilled.push({ role: 'Senior Estimator', field: 'leadEstimator', count: need.senior });
  if (need.lead1  > 0 && !(project.leadAssignee1 || '').trim()) unfilled.push({ role: 'Lead Assignee 1', field: 'leadAssignee1', count: need.lead1 });
  if (need.lead2  > 0 && !(project.leadAssignee2 || '').trim()) unfilled.push({ role: 'Lead Assignee 2', field: 'leadAssignee2', count: need.lead2 });
  if (unfilled.length === 0) return;
  // For each unfilled role, prompt for a name. User can leave blank to skip.
  // Lines listing how many tasks are affected give the user context.
  const summary = unfilled.map(u => `• ${u.role}: ${u.count} task${u.count === 1 ? '' : 's'} require this role`).join('\n');
  const proceed = confirm(
    `${unfilled.length} project role${unfilled.length === 1 ? '' : 's'} not yet filled:\n\n` +
    `${summary}\n\n` +
    `Want to assign them now? Click OK to be prompted for each role, or Cancel to load the template anyway (those tasks will load with fewer auto-leads — you can fill them in manually later).`
  );
  if (!proceed) return;
  unfilled.forEach(u => {
    const name = prompt(`Who is the ${u.role} on this project?\n\n(Leave blank to skip — the ${u.count} task${u.count === 1 ? '' : 's'} requiring this role will load without an auto-assigned lead for it.)`, '');
    if (name && name.trim()) {
      project[u.field] = name.trim();
    }
  });
  // The newly-set role values are picked up by _addTemplateTasksToProject
  // when it reads project.leadEstimator / leadAssignee1 / leadAssignee2.
}

// Detect role changes after a project edit and offer to propagate them.
// For each role that changed: count tasks where the OLD person is in the
// task's leads list, prompt the user, swap on confirmation.
function _promptPropagateRoleChange(project, oldRoles) {
  if (!project || !oldRoles) return;
  // Build a list of role-changes worth propagating: old !== new AND old is non-empty
  const changes = [];
  if ((oldRoles.leadEstimator || '') !== (project.leadEstimator || '') && (oldRoles.leadEstimator || '').trim()) {
    changes.push({ role: 'Senior Estimator', oldName: oldRoles.leadEstimator.trim(), newName: (project.leadEstimator || '').trim() });
  }
  if ((oldRoles.leadAssignee1 || '') !== (project.leadAssignee1 || '') && (oldRoles.leadAssignee1 || '').trim()) {
    changes.push({ role: 'Lead Assignee 1', oldName: oldRoles.leadAssignee1.trim(), newName: (project.leadAssignee1 || '').trim() });
  }
  if ((oldRoles.leadAssignee2 || '') !== (project.leadAssignee2 || '') && (oldRoles.leadAssignee2 || '').trim()) {
    changes.push({ role: 'Lead Assignee 2', oldName: oldRoles.leadAssignee2.trim(), newName: (project.leadAssignee2 || '').trim() });
  }
  if (changes.length === 0) return;
  // For each change, count affected tasks (those where the old person is a Lead)
  // and prompt the user task-by-task. Confirm = swap; Cancel = leave.
  changes.forEach(c => {
    const oldNameLower = c.oldName.toLowerCase();
    const affected = project.tasks.filter(t => {
      const leads = Array.isArray(t.leads) ? t.leads : (t.assignee ? [t.assignee] : []);
      return leads.some(n => (n || '').trim().toLowerCase() === oldNameLower);
    });
    if (affected.length === 0) return;
    const replaceMsg = c.newName
      ? `Update ${affected.length} existing task${affected.length === 1 ? '' : 's'} to swap "${c.oldName}" → "${c.newName}"?`
      : `Remove "${c.oldName}" from ${affected.length} existing task${affected.length === 1 ? '' : 's'}?\n\n(The ${c.role} slot is now empty.)`;
    const ok = confirm(`${c.role} changed from "${c.oldName}" to "${c.newName || '(empty)'}"\n\n${replaceMsg}`);
    if (!ok) return;
    affected.forEach(t => {
      const leads = Array.isArray(t.leads) ? t.leads.slice() : (t.assignee ? [t.assignee] : []);
      const idx = leads.findIndex(n => (n || '').trim().toLowerCase() === oldNameLower);
      if (idx === -1) return;
      if (c.newName) {
        // Swap, but skip if newName is already in the list (avoid duplicates)
        if (leads.some(n => (n || '').trim().toLowerCase() === c.newName.toLowerCase())) {
          // duplicate — just remove the old one
          leads.splice(idx, 1);
        } else {
          leads[idx] = c.newName;
        }
      } else {
        // Empty newName → remove the old name entry
        leads.splice(idx, 1);
      }
      t.leads = leads;
      // Mirror first lead to legacy assignee field for backward compat
      t.assignee = leads[0] || '';
    });
  });
  saveState();
  if (typeof renderProject === 'function') renderProject();
}

// =============================================================
// HEADER STATUS PILL (v58)
// Click the navy header's status pill to open a small popover with
// the 5 status options. Selecting one updates the hidden Column 1
// select (so save logic stays unchanged) AND the pill display.
// =============================================================

const _STATUS_LABELS = {
  'not-started': 'Not Started',
  'in-progress': 'In Progress',
  'blocked':     'Blocked / RFI',
  'pending':     'Pending – Waiting',
  'done':        'Complete'
};

// Refresh the pill's data-status, label, and visibility from the underlying
// taskStatus select. Called from openTaskModal after the form values load,
// and any time the user picks a status from either UI surface.
function refreshHeaderStatusPill() {
  const sel = document.getElementById('taskStatus');
  const pill = document.getElementById('tmpcStatus');
  const label = document.getElementById('tmpcStatusLabel');
  if (!sel || !pill || !label) return;
  const status = sel.value || 'not-started';
  pill.setAttribute('data-status', status);
  label.textContent = _STATUS_LABELS[status] || 'Status';
  // Show pill only when project chip is showing (i.e. modal has a project context)
  const chip = document.getElementById('taskModalProjectChip');
  if (chip && chip.style.display !== 'none') {
    pill.style.display = 'flex';
  } else {
    // Even without project chip, still show on existing tasks; only hide for new-task
    // mode if the chip isn't shown
    pill.style.display = 'none';
  }
  // Close the picker if it was open
  const picker = document.getElementById('tmpcStatusPicker');
  if (picker) picker.style.display = 'none';
}

// Toggle the inline picker open/closed.
function toggleHeaderStatusPicker(ev) {
  if (ev) ev.stopPropagation();
  const picker = document.getElementById('tmpcStatusPicker');
  if (!picker) return;
  if (picker.style.display === 'none' || !picker.style.display) {
    picker.style.display = 'flex';
    // Close on outside click
    setTimeout(() => {
      document.addEventListener('click', _closeHeaderStatusPickerOnOutside, { once: true });
    }, 0);
  } else {
    picker.style.display = 'none';
  }
}

function _closeHeaderStatusPickerOnOutside(ev) {
  const picker = document.getElementById('tmpcStatusPicker');
  const pill = document.getElementById('tmpcStatus');
  if (!picker) return;
  if (pill && pill.contains(ev.target)) return; // click on pill itself — toggle handles
  picker.style.display = 'none';
}

// User picked a status from the header picker. Update the underlying
// <select> (so save flow stays the same) and refresh the pill display.
function setHeaderStatus(ev, newStatus) {
  if (ev) ev.stopPropagation();
  const sel = document.getElementById('taskStatus');
  if (!sel) return;
  sel.value = newStatus;
  // Fire 'change' event so any onchange handlers attached to the select fire too
  sel.dispatchEvent(new Event('change', { bubbles: true }));
  refreshHeaderStatusPill();
}

// =============================================================
// HEADER LEAD/SUPPORT AVATARS + BALL-IN-COURT PILL (v59)
// Avatars are read-only displays; clicking scroll-and-focuses the
// underlying picker in Column 2. Ball-in-Court pill follows the same
// pattern as the Status pill (clickable popover with options).
// =============================================================

const _BIC_DEFAULT_OPTIONS = ['Lead', 'Support', 'Owner', 'Architect', 'Sub', 'Engineer', 'GC', 'Internal'];

// Build initials for an avatar. "John Smith" → "JS"; single name → first 2 chars.
function _avatarInitials(name) {
  if (!name) return '?';
  const parts = name.trim().split(/\s+/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name.trim().slice(0, 2).toUpperCase();
}

// Refresh the lead avatar stack on the header. Reads from the in-modal
// staging arrays (mlpChips DOM since that's the truth-source while editing).
// Falls back to task.leads / task.assignee if the chips aren't rendered yet.
function refreshHeaderLeadStack() {
  const stack = document.getElementById('tmpcLeadStack');
  const avatarsEl = document.getElementById('tmpcLeadAvatars');
  if (!stack || !avatarsEl) return;
  // Pull leads from the chip DOM (truth-source while editing). Each chip
  // has a data-name attribute set by renderMlpChips. Fall back to reading
  // the task object if chips aren't populated yet.
  let leads = [];
  const chipsContainer = document.getElementById('mlpChips');
  if (chipsContainer) {
    chipsContainer.querySelectorAll('[data-name]').forEach(el => {
      const n = el.getAttribute('data-name');
      if (n && !leads.includes(n)) leads.push(n);
    });
  }
  if (leads.length === 0 && editingTaskId) {
    const project = state.projects.find(p => p.id === state.activeProjectId);
    const task = project && project.tasks.find(t => t.id === editingTaskId);
    if (task) {
      if (Array.isArray(task.leads)) leads = task.leads.filter(Boolean);
      else if (task.assignee) leads = [task.assignee];
    }
  }
  if (leads.length === 0) {
    stack.style.display = 'none';
    return;
  }
  stack.style.display = 'flex';
  // Render up to 5 avatars; show "+N" for the rest
  const MAX_AVATARS = 5;
  const visible = leads.slice(0, MAX_AVATARS);
  const overflow = leads.length - visible.length;
  let html = visible.map(name => `
    <span class="tmpc-avatar" style="background:${avatarColor(name)};" title="${escapeAttr(name)}">${_avatarInitials(name)}</span>
  `).join('');
  if (overflow > 0) {
    html += `<span class="tmpc-avatar-overflow" title="${overflow} more lead${overflow === 1 ? '' : 's'}: ${escapeAttr(leads.slice(MAX_AVATARS).join(', '))}">+${overflow}</span>`;
  }
  avatarsEl.innerHTML = html;
}

// Same as refreshHeaderLeadStack but for support members.
function refreshHeaderSupportStack() {
  const stack = document.getElementById('tmpcSupportStack');
  const avatarsEl = document.getElementById('tmpcSupportAvatars');
  if (!stack || !avatarsEl) return;
  let support = [];
  const chipsContainer = document.getElementById('mspChips');
  if (chipsContainer) {
    chipsContainer.querySelectorAll('[data-name]').forEach(el => {
      const n = el.getAttribute('data-name');
      if (n && !support.includes(n)) support.push(n);
    });
  }
  if (support.length === 0 && editingTaskId) {
    const project = state.projects.find(p => p.id === state.activeProjectId);
    const task = project && project.tasks.find(t => t.id === editingTaskId);
    if (task) {
      if (Array.isArray(task.supportMembers)) support = task.supportMembers.filter(Boolean);
      else if (task.support) support = [task.support];
    }
  }
  if (support.length === 0) {
    stack.style.display = 'none';
    return;
  }
  stack.style.display = 'flex';
  const MAX_AVATARS = 5;
  const visible = support.slice(0, MAX_AVATARS);
  const overflow = support.length - visible.length;
  let html = visible.map(name => `
    <span class="tmpc-avatar" style="background:${avatarColor(name)};" title="${escapeAttr(name)}">${_avatarInitials(name)}</span>
  `).join('');
  if (overflow > 0) {
    html += `<span class="tmpc-avatar-overflow" title="${overflow} more support: ${escapeAttr(support.slice(MAX_AVATARS).join(', '))}">+${overflow}</span>`;
  }
  avatarsEl.innerHTML = html;
}

// Click handler — scroll-and-focus the matching picker input in Column 2.
// fieldId is the ID of the input element to focus (taskAssignee for leads,
// taskSupport for support members).
function scrollToHeaderField(ev, fieldId) {
  if (ev) ev.stopPropagation();
  const target = document.getElementById(fieldId);
  if (!target) return;
  // Smooth-scroll the modal so the target is visible
  const modal = document.querySelector('#taskModal .modal');
  if (modal && target.scrollIntoView) {
    target.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
  setTimeout(() => target.focus(), 250);
}

// Refresh the Ball-in-Court pill from the underlying #taskBallInCourt select.
function refreshHeaderBicPill() {
  const sel = document.getElementById('taskBallInCourt');
  const pill = document.getElementById('tmpcBic');
  const label = document.getElementById('tmpcBicLabel');
  const picker = document.getElementById('tmpcBicPicker');
  if (!sel || !pill || !label || !picker) return;
  const value = sel.value || 'Lead';
  label.textContent = value;
  // Show pill when project chip is showing
  const chip = document.getElementById('taskModalProjectChip');
  if (chip && chip.style.display !== 'none') {
    pill.style.display = 'flex';
  } else {
    pill.style.display = 'none';
  }
  // Build picker options from the underlying <select>'s actual options so
  // it stays in sync with whatever the user has configured. Fall back to
  // defaults if the select is empty.
  const options = Array.from(sel.options).map(o => o.value).filter(Boolean);
  const opts = options.length > 0 ? options : _BIC_DEFAULT_OPTIONS;
  picker.innerHTML = opts.map(opt => `
    <button type="button" class="tmpc-bic-opt ${opt === value ? 'active' : ''}" onclick="setHeaderBic(event, '${escapeAttr(opt)}')">${escapeHtml(opt)}</button>
  `).join('');
  // Close picker if open
  picker.style.display = 'none';
}

function toggleHeaderBicPicker(ev) {
  if (ev) ev.stopPropagation();
  const picker = document.getElementById('tmpcBicPicker');
  if (!picker) return;
  if (picker.style.display === 'none' || !picker.style.display) {
    picker.style.display = 'flex';
    setTimeout(() => {
      document.addEventListener('click', _closeHeaderBicPickerOnOutside, { once: true });
    }, 0);
  } else {
    picker.style.display = 'none';
  }
}

function _closeHeaderBicPickerOnOutside(ev) {
  const picker = document.getElementById('tmpcBicPicker');
  const pill = document.getElementById('tmpcBic');
  if (!picker) return;
  if (pill && pill.contains(ev.target)) return;
  picker.style.display = 'none';
}

function setHeaderBic(ev, newValue) {
  if (ev) ev.stopPropagation();
  const sel = document.getElementById('taskBallInCourt');
  if (!sel) return;
  sel.value = newValue;
  sel.dispatchEvent(new Event('change', { bubbles: true }));
  refreshHeaderBicPill();
}

// Aggregate refresh — call after openTaskModal sets up the form. Refreshes
// all header pills and avatars in one call.
function refreshAllHeaderPills() {
  refreshHeaderStatusPill();
  refreshHeaderLeadStack();
  refreshHeaderSupportStack();
  refreshHeaderBicPill();
}

function closeModal(id) { document.getElementById(id).classList.remove('active'); }

// =============================================================
// VIEW MODE & GROUPING
// =============================================================
function setViewMode(mode) {
  state.viewMode = mode;
  if (typeof clearActiveSavedView === 'function') clearActiveSavedView();
  saveState();
  document.querySelectorAll('[data-viewmode]').forEach(b => b.classList.toggle('active', b.dataset.viewmode === mode));
  render();
}
// =============================================================
// v98: Workspace Grouping — collapsible header
// The workspace controls have a Grouping & Filters section that shows
// all Group By modes + a stage/assignee/status/etc. pill row + optional
// alert filter rows. When there are many stages, this pushes the board
// or table view down the page. Toggle collapses the whole cluster to
// a compact header so more room is given to the actual view.
// =============================================================
function toggleWorkspaceGrouping() {
  state.workspaceGroupingCollapsed = !state.workspaceGroupingCollapsed;
  saveState();
  _applyWorkspaceGroupingCollapseState();
}

// Apply persisted collapse state + refresh the summary chip that shows
// current grouping mode + selected tab when collapsed. Called on every
// render so the chip stays in sync with any state changes.
function _applyWorkspaceGroupingCollapseState() {
  const section = document.getElementById('groupingSection');
  if (!section) return;
  const collapsed = !!state.workspaceGroupingCollapsed;
  section.classList.toggle('grouping-collapsed', collapsed);
  const summary = document.getElementById('pvWcGroupingSummary');
  if (!summary) return;
  if (collapsed) {
    summary.textContent = _buildWorkspaceGroupingSummary();
  } else {
    summary.textContent = '';
  }
}

// Build a compact summary string for the collapsed Filters header — since
// the Group By tabs are always visible above (per v99), the chip only
// needs to reflect the currently selected pill tab plus any secondary
// filter that's active. Keeps the chip short and unambiguous.
function _buildWorkspaceGroupingSummary() {
  const groupingKey = state.grouping || 'stage';
  let tabLabel = '';
  if (groupingKey === 'stage') {
    const stageId = state.activeStageId || 'all';
    if (stageId === 'all') tabLabel = 'All Stages';
    else {
      const stage = (state.stages || []).find(s => s.id === stageId);
      tabLabel = stage ? stage.name : stageId;
    }
  } else if (groupingKey === 'assignee') {
    tabLabel = (state.activeAssignee === 'all') ? 'All People' : (state.activeAssignee || 'All People');
  } else if (groupingKey === 'source') {
    tabLabel = (state.activeSource === 'all') ? 'All Sources' : (state.activeSource || 'All Sources');
  } else if (groupingKey === 'status') {
    const statusLabels = {
      'all': 'All Statuses',
      'not-started': 'Not Started',
      'in-progress': 'In Progress',
      'blocked': 'Blocked',
      'pending': 'Pending',
      'done': 'Done'
    };
    tabLabel = statusLabels[state.activeStatus || 'all'] || 'All Statuses';
  } else if (groupingKey === 'alert') {
    tabLabel = (state.activeAlertTier === 'all' || !state.activeAlertTier) ? 'All Alerts' : state.activeAlertTier;
  } else if (groupingKey === 'my-alert') {
    tabLabel = (state.activeMyAlertTier === 'all' || !state.activeMyAlertTier) ? 'All Alerts (mine)' : state.activeMyAlertTier;
  }
  // Include any secondary assignee filter if active
  let extras = '';
  if (state.secondaryAssigneeFilter && state.secondaryAssigneeFilter !== 'all') {
    extras = ` · assignee: ${state.secondaryAssigneeFilter}`;
  }
  return `${tabLabel}${extras}`;
}

function setGrouping(g) {
  state.grouping = g;
  if (g === 'stage') state.activeStageId = 'all';
  else if (g === 'assignee') state.activeAssignee = 'all';
  else if (g === 'source') state.activeSource = 'all';
  else if (g === 'status') state.activeStatus = 'all';
  else if (g === 'alert') state.activeAlertTier = 'all';
  else if (g === 'my-alert') state.activeMyAlertTier = 'all';
  if (typeof clearActiveSavedView === 'function') clearActiveSavedView();
  saveState();
  document.querySelectorAll('[data-grouping]').forEach(b => b.classList.toggle('active', b.dataset.grouping === g));
  render();
}

// Secondary filter — narrows whatever the current grouping is to a single
// assignee (or 'unassigned'). Applied AFTER the primary group filter so a
// user can do things like "show me Blocked tasks assigned to John" or
// "Project Setup tasks assigned to Sarah." Hidden in Assignee grouping
// where it'd be redundant (the grouping already does this).
function setSecondaryAssigneeFilter(value) {
  state.secondaryAssigneeFilter = value || 'all';
  if (typeof clearActiveSavedView === 'function') clearActiveSavedView();
  saveState();
  render();
}

// Multi-filter setter for Group by Alert mode. `dim` is one of
// 'assignee' | 'stage' | 'source'.
function setAlertFilter(dim, value) {
  if (!state.alertFilters) state.alertFilters = { assignee: 'all', stage: 'all', source: 'all' };
  state.alertFilters[dim] = value || 'all';
  saveState();
  render();
}

// One-click reset for all three filters
function clearAllAlertFilters() {
  state.alertFilters = { assignee: 'all', stage: 'all', source: 'all' };
  saveState();
  render();
}

// === MY-ALERT FILTERS ===
function setMyAlertFilter(dim, value) {
  if (!state.myAlertFilters) state.myAlertFilters = { stage: 'all', source: 'all' };
  state.myAlertFilters[dim] = value || 'all';
  saveState();
  render();
}

function clearAllMyAlertFilters() {
  state.myAlertFilters = { stage: 'all', source: 'all' };
  saveState();
  render();
}

// Render the My Alerts multi-filter row. Two dropdowns — stage + source —
// (assignee is fixed to "me" so omitted). Counts within the active tier
// scoped to the current user.
function renderMyAlertMultiFilter() {
  const row = document.getElementById('myAlertFilterRow');
  if (!row) return;
  if (state.grouping !== 'my-alert') {
    row.style.display = 'none';
    return;
  }
  row.style.display = 'flex';

  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) {
    row.style.display = 'none';
    return;
  }

  // Tier-filtered tasks scoped to the current user (BEFORE the multi-filter)
  const tierTasks = filterTasksByAlertTierScoped(project, state.activeMyAlertTier, 'my');

  // === STAGE DROPDOWN ===
  const stageSel = document.getElementById('myAlertFilterStage');
  if (stageSel) {
    const current = (state.myAlertFilters && state.myAlertFilters.stage) || 'all';
    const opts = [`<option value="all"${current === 'all' ? ' selected' : ''}>All Stages</option>`];
    STAGES.forEach(s => {
      const count = tierTasks.filter(t => t.stage === s.id).length;
      if (count === 0) return;
      opts.push(`<option value="${escapeAttr(s.id)}"${current === s.id ? ' selected' : ''}>${s.icon} ${escapeHtml(s.name)} (${count})</option>`);
    });
    stageSel.innerHTML = opts.join('');
    if (current !== 'all') {
      const stillExists = Array.from(stageSel.options).some(o => o.value === current);
      if (!stillExists) stageSel.value = 'all';
    }
  }

  // === SOURCE DROPDOWN ===
  const sourceSel = document.getElementById('myAlertFilterSource');
  if (sourceSel) {
    const current = (state.myAlertFilters && state.myAlertFilters.source) || 'all';
    const sourceMap = new Map();
    tierTasks.forEach(t => {
      const s = (t.source || '').trim();
      if (!s) return;
      sourceMap.set(s, (sourceMap.get(s) || 0) + 1);
    });
    const unsourcedCount = tierTasks.filter(t => !t.source || !t.source.trim()).length;
    const opts = [`<option value="all"${current === 'all' ? ' selected' : ''}>All Sources</option>`];
    if (unsourcedCount > 0) {
      opts.push(`<option value="unsourced"${current === 'unsourced' ? ' selected' : ''}>— Unsourced — (${unsourcedCount})</option>`);
    }
    Array.from(sourceMap.keys()).sort().forEach(name => {
      opts.push(`<option value="${escapeAttr(name)}"${current === name ? ' selected' : ''}>${escapeHtml(name)} (${sourceMap.get(name)})</option>`);
    });
    sourceSel.innerHTML = opts.join('');
    if (current !== 'all' && current !== 'unsourced') {
      const stillExists = Array.from(sourceSel.options).some(o => o.value === current);
      if (!stillExists) sourceSel.value = 'all';
    }
  }

  // === META + CLEAR-ALL ===
  const f = state.myAlertFilters || {};
  const anyActive = (f.stage && f.stage !== 'all') || (f.source && f.source !== 'all');
  row.classList.toggle('afr-active', anyActive);
  const clearBtn = document.getElementById('myAfrClearBtn');
  if (clearBtn) clearBtn.style.display = anyActive ? 'inline-flex' : 'none';

  const meta = document.getElementById('myAfrMeta');
  if (meta) {
    if (anyActive) {
      const filtered = getFilteredTasks(project).length;
      const parts = [];
      if (f.stage && f.stage !== 'all') {
        const stage = STAGES.find(s => s.id === f.stage);
        if (stage) parts.push(stage.name);
      }
      if (f.source && f.source !== 'all') parts.push(f.source === 'unsourced' ? 'unsourced' : f.source);
      meta.textContent = `→ ${filtered} of your task${filtered === 1 ? '' : 's'} matching ${parts.join(' · ')}`;
    } else {
      meta.textContent = `${tierTasks.length} of your task${tierTasks.length === 1 ? '' : 's'} in this tier`;
    }
  }
}

// Render the multi-filter row used in Group by Alert. Three dropdowns —
// assignee, stage, source — with live counts within the active alert tier
// so users see "Trent (5)" reflecting just the at-risk tasks Trent owns,
// not his entire workload.
function renderAlertMultiFilter() {
  const row = document.getElementById('alertFilterRow');
  if (!row) return;
  // Hide unless we're in alert grouping mode
  if (state.grouping !== 'alert') {
    row.style.display = 'none';
    return;
  }
  row.style.display = 'flex';

  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) {
    row.style.display = 'none';
    return;
  }

  // Compute the tier-filtered task pool (BEFORE multi-filter is applied)
  // so the dropdown counts reflect "within the active tier" not "total."
  const tierTasks = filterTasksByAlertTier(project, state.activeAlertTier);

  // === ASSIGNEE DROPDOWN ===
  const assigneeSel = document.getElementById('alertFilterAssignee');
  if (assigneeSel) {
    const rosterNames = (state.teamMembers || []).map(m => m.name);
    const taskNames = project.tasks.map(t => t.assignee).filter(Boolean);
    const supportNames = [];
    project.tasks.forEach(t => {
      const all = (typeof getAllSupportMembers === 'function') ? getAllSupportMembers(t) : [];
      all.forEach(name => supportNames.push(name));
    });
    const allPeople = Array.from(new Set([...rosterNames, ...taskNames, ...supportNames])).sort();

    const unassignedCount = tierTasks.filter(t => !t.assignee || !t.assignee.trim()).length;
    const current = (state.alertFilters && state.alertFilters.assignee) || 'all';
    const opts = [`<option value="all"${current === 'all' ? ' selected' : ''}>All Assignees</option>`];
    if (unassignedCount > 0) {
      opts.push(`<option value="unassigned"${current === 'unassigned' ? ' selected' : ''}>— Unassigned — (${unassignedCount})</option>`);
    }
    allPeople.forEach(n => {
      const count = tierTasks.filter(t => (t.assignee||'').trim() === n || isTaskSupport(t, n)).length;
      if (count === 0) return;
      opts.push(`<option value="${escapeAttr(n)}"${current === n ? ' selected' : ''}>${escapeHtml(n)} (${count})</option>`);
    });
    assigneeSel.innerHTML = opts.join('');
    if (current !== 'all' && current !== 'unassigned') {
      const stillExists = Array.from(assigneeSel.options).some(o => o.value === current);
      if (!stillExists) assigneeSel.value = 'all';
    }
  }

  // === STAGE DROPDOWN ===
  const stageSel = document.getElementById('alertFilterStage');
  if (stageSel) {
    const current = (state.alertFilters && state.alertFilters.stage) || 'all';
    const opts = [`<option value="all"${current === 'all' ? ' selected' : ''}>All Stages</option>`];
    STAGES.forEach(s => {
      const count = tierTasks.filter(t => t.stage === s.id).length;
      if (count === 0) return;
      opts.push(`<option value="${escapeAttr(s.id)}"${current === s.id ? ' selected' : ''}>${s.icon} ${escapeHtml(s.name)} (${count})</option>`);
    });
    stageSel.innerHTML = opts.join('');
    if (current !== 'all') {
      const stillExists = Array.from(stageSel.options).some(o => o.value === current);
      if (!stillExists) stageSel.value = 'all';
    }
  }

  // === SOURCE DROPDOWN ===
  const sourceSel = document.getElementById('alertFilterSource');
  if (sourceSel) {
    const current = (state.alertFilters && state.alertFilters.source) || 'all';
    const sourceMap = new Map();
    tierTasks.forEach(t => {
      const s = (t.source || '').trim();
      if (!s) return;
      sourceMap.set(s, (sourceMap.get(s) || 0) + 1);
    });
    const unsourcedCount = tierTasks.filter(t => !t.source || !t.source.trim()).length;
    const opts = [`<option value="all"${current === 'all' ? ' selected' : ''}>All Sources</option>`];
    if (unsourcedCount > 0) {
      opts.push(`<option value="unsourced"${current === 'unsourced' ? ' selected' : ''}>— Unsourced — (${unsourcedCount})</option>`);
    }
    Array.from(sourceMap.keys()).sort().forEach(name => {
      opts.push(`<option value="${escapeAttr(name)}"${current === name ? ' selected' : ''}>${escapeHtml(name)} (${sourceMap.get(name)})</option>`);
    });
    sourceSel.innerHTML = opts.join('');
    if (current !== 'all' && current !== 'unsourced') {
      const stillExists = Array.from(sourceSel.options).some(o => o.value === current);
      if (!stillExists) sourceSel.value = 'all';
    }
  }

  // === META + CLEAR-ALL ===
  const f = state.alertFilters || {};
  const anyActive = (f.assignee && f.assignee !== 'all') || (f.stage && f.stage !== 'all') || (f.source && f.source !== 'all');
  row.classList.toggle('afr-active', anyActive);
  const clearBtn = document.getElementById('afrClearBtn');
  if (clearBtn) clearBtn.style.display = anyActive ? 'inline-flex' : 'none';

  const meta = document.getElementById('afrMeta');
  if (meta) {
    if (anyActive) {
      const filtered = getFilteredTasks(project).length;
      const parts = [];
      if (f.assignee && f.assignee !== 'all') parts.push(f.assignee === 'unassigned' ? 'unassigned' : f.assignee);
      if (f.stage && f.stage !== 'all') {
        const stage = STAGES.find(s => s.id === f.stage);
        if (stage) parts.push(stage.name);
      }
      if (f.source && f.source !== 'all') parts.push(f.source === 'unsourced' ? 'unsourced' : f.source);
      meta.textContent = `→ ${filtered} task${filtered === 1 ? '' : 's'} matching ${parts.join(' · ')}`;
    } else {
      meta.textContent = `${tierTasks.length} task${tierTasks.length === 1 ? '' : 's'} in this tier`;
    }
  }
}

// Build the assignee dropdown for the secondary filter row. Pulls from team
// roster + any task assignees not yet in roster + support members, matching
// how populateAssigneeDatalist works for the task modal. Includes special
// 'unassigned' bucket since unassigned-but-overdue tasks are a common
// "needs Lead attention" pattern.
function renderSecondaryAssigneeFilter() {
  const row = document.getElementById('secondaryFilterRow');
  const select = document.getElementById('secondaryAssigneeFilterSelect');
  const meta = document.getElementById('sfrMeta');
  const clearBtn = document.getElementById('sfrClearBtn');
  if (!row || !select) return;

  // Hide entirely in Assignee grouping mode — would be redundant
  // Also hide in Alert / My Alerts grouping modes — they use their own filter rows
  if (state.grouping === 'assignee' || state.grouping === 'alert' || state.grouping === 'my-alert') {
    row.style.display = 'none';
    return;
  }
  row.style.display = 'flex';

  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) {
    row.style.display = 'none';
    return;
  }

  // Build the option list — same union as the task modal's assignee datalist
  const rosterNames = (state.teamMembers || []).map(m => m.name);
  const taskNames = project.tasks.map(t => t.assignee).filter(Boolean);
  const supportNames = [];
  project.tasks.forEach(t => {
    const all = (typeof getAllSupportMembers === 'function') ? getAllSupportMembers(t) : [];
    all.forEach(name => supportNames.push(name));
  });
  const all = Array.from(new Set([...rosterNames, ...taskNames, ...supportNames])).sort();

  // Count tasks per person within the CURRENT primary group, so the dropdown
  // shows live counts ("John (12)" etc.) that reflect the active grouping
  const tasksInGroup = getTasksInPrimaryGroup(project);
  const countFor = (name) => {
    if (name === 'unassigned') return tasksInGroup.filter(t => !t.assignee || !t.assignee.trim()).length;
    return tasksInGroup.filter(t => (t.assignee||'').trim() === name || isTaskSupport(t, name)).length;
  };

  // Always include 'unassigned' if there are any unassigned tasks in the group
  const unassignedCount = tasksInGroup.filter(t => !t.assignee || !t.assignee.trim()).length;

  const current = state.secondaryAssigneeFilter || 'all';
  const opts = [`<option value="all">All Assignees · ${tasksInGroup.length} task${tasksInGroup.length === 1 ? '' : 's'}</option>`];
  if (unassignedCount > 0) {
    opts.push(`<option value="unassigned"${current === 'unassigned' ? ' selected' : ''}>— Unassigned — (${unassignedCount})</option>`);
  }
  all.forEach(n => {
    const count = countFor(n);
    if (count === 0) return; // skip people with no tasks in current group
    opts.push(`<option value="${escapeAttr(n)}"${current === n ? ' selected' : ''}>${escapeHtml(n)} (${count})</option>`);
  });
  select.innerHTML = opts.join('');
  // If the previously-selected name has zero tasks in the new group, the
  // dropdown won't include it — make sure 'all' is shown selected
  if (current !== 'all' && current !== 'unassigned') {
    const stillExists = Array.from(select.options).some(o => o.value === current);
    if (!stillExists) select.value = 'all';
  }

  // Active-state styling and meta
  const isFiltered = current !== 'all';
  row.classList.toggle('sfr-active', isFiltered);
  if (clearBtn) clearBtn.style.display = isFiltered ? 'inline-flex' : 'none';
  if (meta) {
    if (isFiltered) {
      const filtered = getFilteredTasks(project).length;
      const label = current === 'unassigned' ? 'unassigned' : current;
      meta.textContent = `→ ${filtered} task${filtered === 1 ? '' : 's'} for ${label}`;
    } else {
      meta.textContent = '';
    }
  }
}

// Returns the tasks within the CURRENT primary group, BEFORE the secondary
// assignee filter is applied. Used so the assignee dropdown can show
// per-person counts within the active group, and so the meta line can
// compare "filtered vs. group total" honestly.
function getTasksInPrimaryGroup(project) {
  if (state.grouping === 'stage') {
    if (state.activeStageId === 'all') return project.tasks.slice();
    return project.tasks.filter(t => t.stage === state.activeStageId);
  } else if (state.grouping === 'source') {
    if (state.activeSource === 'all') return project.tasks.slice();
    if (state.activeSource === 'unsourced') return project.tasks.filter(t => !t.source || !t.source.trim());
    return project.tasks.filter(t => (t.source || '').trim() === state.activeSource);
  } else if (state.grouping === 'status') {
    if (state.activeStatus === 'all') return project.tasks.slice();
    return project.tasks.filter(t => t.status === state.activeStatus);
  }
  // For 'assignee' grouping, fall back to all tasks (filter row is hidden anyway)
  return project.tasks.slice();
}

// =============================================================
// PRINT / SAVE AS PDF
// =============================================================
function printView() {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) { alert('Select a project first'); return; }

  // Populate print header meta
  const viewLabels = { board: 'Board View', table: 'Table View', calendar: 'Calendar View' };
  const calRangeLabels = { day: 'Day', week: 'Week', '2week': '2-Week Look Ahead', month: 'Month' };

  const total = project.tasks.length;
  const done = project.tasks.filter(t => t.status === 'done').length;
  const overdueCount = project.tasks.filter(t => isTaskOverdue(t)).length;
  const pct = total > 0 ? Math.round((done/total)*100) : 0;

  let viewTag = viewLabels[state.viewMode] || 'View';
  if (state.viewMode === 'calendar') {
    viewTag = `Calendar · ${calRangeLabels[state.calRange] || ''}`;
  }

  let groupTag = '';
  if (state.viewMode !== 'calendar') {
    if (state.grouping === 'stage') {
      const stage = STAGES.find(s => s.id === state.activeStageId);
      groupTag = state.activeStageId === 'all' ? 'All Stages' : (stage ? stage.name : '');
    } else if (state.grouping === 'source') {
      groupTag = state.activeSource === 'all' ? 'All Sources' :
                 state.activeSource === 'unsourced' ? 'No Source' : state.activeSource;
    } else if (state.grouping === 'status') {
      const statusLabels = {
        'all': 'All Statuses',
        'not-started': 'Not Started',
        'in-progress': 'In Progress',
        'blocked': 'Blocked',
        'pending': 'Pending',
        'done': 'Done'
      };
      groupTag = statusLabels[state.activeStatus] || state.activeStatus;
    } else {
      groupTag = state.activeAssignee === 'all' ? 'All Team' :
                 state.activeAssignee === 'unassigned' ? 'Unassigned' : state.activeAssignee;
    }
  } else if (state.calAssignee && state.calAssignee !== 'all') {
    groupTag = state.calAssignee === 'unassigned' ? 'Unassigned' : state.calAssignee;
  }

  const meta = [
    `<strong>${escapeHtml(project.name)}</strong>`,
    project.client ? `Owner: ${escapeHtml(project.client)}` : '',
    project.dueDate ? `Bid Due: ${formatDate(project.dueDate)}` : '',
    `Progress: ${done}/${total} (${pct}%)`,
    overdueCount > 0 ? `<span style="color:#c8322b;font-weight:700;">Overdue: ${overdueCount}</span>` : '',
    `View: ${viewTag}${groupTag ? ' · ' + escapeHtml(groupTag) : ''}`,
    `Printed: ${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}`
  ].filter(Boolean).join(' &nbsp;|&nbsp; ');

  document.getElementById('printHeaderMeta').innerHTML = meta;

  // For calendar "all stages" board view would be too sparse; ensure we render the current state first
  // Render ensures DOM is up to date
  render();

  // Small delay allows browser to apply classes then open print dialog
  setTimeout(() => window.print(), 150);
}

