function getDefaultSourceOptions() {
  // Icon: a category-suggesting emoji used as a generic placeholder.
  // photo: optional user-uploaded image (base64 data URL) — shown in place of the icon
  // when present. Use this to paste in your own logos that you have rights to display.
  return [
    { name: 'Bluebeam',          icon: '📐', photo: null },
    { name: 'Building Connected', icon: '🔗', photo: null },
    { name: 'Excel Form',         icon: '📊', photo: null },
    { name: 'Word File',          icon: '📄', photo: null },
    { name: 'SharePoint',         icon: '☁',  photo: null },
    { name: 'Procore',            icon: '🏗', photo: null },
    { name: 'Email',              icon: '✉',  photo: null },
    { name: 'SmartBid',           icon: '💼', photo: null },
    { name: 'iSqFt',              icon: '📋', photo: null },
    { name: 'Other',              icon: '📥', photo: null }
  ];
}

// Suggest a sensible default emoji for any new source name based on common keywords.
// User can always override with their own emoji or upload a photo.
function suggestSourceIcon(name) {
  if (!name) return '📥';
  const n = name.toLowerCase();
  if (/email|gmail|outlook|inbox/.test(n)) return '✉';
  if (/excel|sheet|spreadsheet|xlsx|csv/.test(n)) return '📊';
  if (/word|doc|docx/.test(n)) return '📄';
  if (/pdf/.test(n)) return '📕';
  if (/bluebeam|markup|takeoff|drawing|plan/.test(n)) return '📐';
  if (/building.?connected|bc/.test(n)) return '🔗';
  if (/procore|project.?management|pm tool/.test(n)) return '🏗';
  if (/sharepoint|onedrive|dropbox|box|drive|cloud/.test(n)) return '☁';
  if (/smartbid|isqft|bid.?clerk|dodge|construct.?connect/.test(n)) return '💼';
  if (/teams|slack|chat|message/.test(n)) return '💬';
  if (/phone|call|voicemail|text|sms/.test(n)) return '📞';
  if (/meeting|conference|zoom|webex/.test(n)) return '👥';
  if (/site|walk|jobsite|field/.test(n)) return '🏗';
  if (/rfp|rfq|rfi|proposal|invitation|invite/.test(n)) return '📨';
  if (/list|clipboard|form|checklist/.test(n)) return '📋';
  if (/portal|web|website|http/.test(n)) return '🌐';
  return '📥';
}

// Find a source option by name (returns null if not found).
function findSourceOption(sourceName) {
  if (!sourceName) return null;
  return (state.sourceOptions || []).find(s => s.name === sourceName) || null;
}

// =============================================================
// KEY MILESTONES — master types + per-project instances
// =============================================================
function getDefaultMilestoneTypes() {
  // defaultDaysBeforeBid: when a project opts in to default offsets, this milestone's
  // date auto-computes as (bid due date - daysBeforeBid). null = no default set.
  return [
    { id: 'trade-partner-bids', name: "Trade Partner Bids Due", icon: '💼', color: '#c8322b', defaultDaysBeforeBid: 1 },
    { id: 'rfi-trade', name: "RFIs Due from Trade Partners", icon: '📨', color: '#1a9ec9', defaultDaysBeforeBid: 7 },
    { id: 'rfi-client', name: "RFIs Due to Client / Architect", icon: '📤', color: '#6e4eb8', defaultDaysBeforeBid: 5 },
    { id: 'bid-leveling', name: "Bid Leveling Review", icon: '📊', color: '#c07f00', defaultDaysBeforeBid: 0 },
    { id: 'exec-review', name: "Executive Review", icon: '🏛', color: '#2e7d52', defaultDaysBeforeBid: 2 }
  ];
}

function getProjectMilestones(project) {
  // Returns the combined view: each master milestoneType paired with its project-level date/time instance.
  // If a project doesn't have an instance for a given type yet, a placeholder is returned with no date/time.
  if (!project) return [];
  const instances = Array.isArray(project.milestones) ? project.milestones : [];
  return state.milestoneTypes.map(type => {
    const inst = instances.find(m => m.typeId === type.id) || { typeId: type.id, date: '', time: '', timezone: '', notes: '' };
    return { type, instance: inst };
  });
}

// Compute a date string from bid due + offset days.
// Returns YYYY-MM-DD format, or empty string if inputs are invalid.
function computeMilestoneDateFromOffset(bidDueDate, daysBefore) {
  if (!bidDueDate) return '';
  if (typeof daysBefore !== 'number' || isNaN(daysBefore)) return '';
  const due = new Date(bidDueDate + 'T00:00:00');
  if (isNaN(due.getTime())) return '';
  const result = new Date(due.getTime() - daysBefore * 86400000);
  // Format as YYYY-MM-DD in local time (avoiding timezone shifts)
  const yyyy = result.getFullYear();
  const mm = String(result.getMonth() + 1).padStart(2, '0');
  const dd = String(result.getDate()).padStart(2, '0');
  const raw = `${yyyy}-${mm}-${dd}`;
  // Respect global skip rules — milestones default-offset off bid due date
  // shift forward to the next business day if they land on weekend/holiday.
  // Manual milestone date entry stays untouched.
  return snapToBusinessDay(raw).date;
}

// Apply default offsets from milestone settings to all project milestones.
// Returns count of milestone instances that got auto-dated.
// `markAuto` = true to flag instances as `defaultOffsetApplied: true` (so future bid date changes also recompute them).
// `overwriteExisting` = true to overwrite manual dates; false to only fill in missing dates.
function applyDefaultOffsetsToProject(project, overwriteExisting) {
  if (!project) return 0;
  const bidDue = project.dueDate;
  if (!bidDue) return 0;
  if (!Array.isArray(project.milestones)) project.milestones = [];

  let count = 0;
  state.milestoneTypes.forEach(type => {
    if (typeof type.defaultDaysBeforeBid !== 'number') return; // no default offset configured
    const computed = computeMilestoneDateFromOffset(bidDue, type.defaultDaysBeforeBid);
    if (!computed) return;

    let inst = project.milestones.find(m => m.typeId === type.id);
    if (!inst) {
      inst = { typeId: type.id, date: '', time: '', timezone: '', notes: '' };
      project.milestones.push(inst);
    }
    if (!overwriteExisting && inst.date) return; // preserve manual entry

    inst.date = computed;
    inst.defaultOffsetApplied = true;
    count++;
  });
  return count;
}

// Recompute auto-dated milestones when a project's bid due date changes.
// Only touches instances flagged with defaultOffsetApplied: true and only when project.useDefaultOffsets is on.
function refreshAutoMilestoneDates(project) {
  if (!project || !project.useDefaultOffsets) return 0;
  if (!project.dueDate) return 0;
  if (!Array.isArray(project.milestones)) return 0;

  let count = 0;
  state.milestoneTypes.forEach(type => {
    if (typeof type.defaultDaysBeforeBid !== 'number') return;
    const inst = project.milestones.find(m => m.typeId === type.id);
    if (!inst || !inst.defaultOffsetApplied) return;
    const computed = computeMilestoneDateFromOffset(project.dueDate, type.defaultDaysBeforeBid);
    if (computed && computed !== inst.date) {
      inst.date = computed;
      count++;
    }
  });
  return count;
}

function getMilestoneMoment(instance) {
  if (!instance || !instance.date) return null;
  const dateStr = instance.date;
  const timeStr = instance.time || '17:00'; // default to 5pm if just a date
  if (instance.timezone) {
    try {
      const isoLocal = `${dateStr}T${timeStr}:00`;
      const asUtc = new Date(isoLocal + 'Z');
      const tzDate = new Date(asUtc.toLocaleString('en-US', { timeZone: instance.timezone }));
      const localDate = new Date(asUtc.toLocaleString('en-US'));
      const offsetMs = tzDate.getTime() - localDate.getTime();
      return new Date(asUtc.getTime() - offsetMs);
    } catch (e) {
      return new Date(`${dateStr}T${timeStr}:00`);
    }
  }
  return new Date(`${dateStr}T${timeStr}:00`);
}

function getMilestoneCountdown(instance) {
  const moment = getMilestoneMoment(instance);
  if (!moment) return null;
  const now = new Date();
  const diff = moment.getTime() - now.getTime();
  const absDiff = Math.abs(diff);
  return {
    totalMs: diff,
    isPast: diff < 0,
    days: Math.floor(absDiff / 86400000),
    hours: Math.floor((absDiff % 86400000) / 3600000),
    minutes: Math.floor((absDiff % 3600000) / 60000),
    seconds: Math.floor((absDiff % 60000) / 1000)
  };
}

function saveProjectMilestone(projectId, typeId, date, time, timezone, notes) {
  const p = state.projects.find(x => x.id === projectId);
  if (!p) return;
  if (!Array.isArray(p.milestones)) p.milestones = [];
  let inst = p.milestones.find(m => m.typeId === typeId);
  // Capture old values for diff logging
  const oldDate = inst ? (inst.date || '') : '';
  const oldTime = inst ? (inst.time || '') : '';
  const oldNotes = inst ? (inst.notes || '') : '';
  if (!inst) {
    inst = { typeId };
    p.milestones.push(inst);
  }
  inst.date = date || '';
  inst.time = time || '';
  inst.timezone = timezone || '';
  inst.notes = notes || '';

  // Activity log: only log if something meaningful changed
  const milestoneType = state.milestoneTypes.find(m => m.id === typeId);
  if (milestoneType) {
    if (oldDate !== inst.date) {
      logMilestoneChanged(p, milestoneType, 'Date', inst.date ? formatDate(inst.date) : '');
    }
    if (oldTime !== inst.time) {
      logMilestoneChanged(p, milestoneType, 'Time', inst.time);
    }
    if (oldNotes !== inst.notes && (oldNotes || inst.notes)) {
      logMilestoneChanged(p, milestoneType, 'Notes', inst.notes ? '(updated)' : '(cleared)');
    }
  }
  saveState();
}

function getSourceNames() {
  return state.sourceOptions.map(s => s.name);
}

function populateSourceSelect() {
  // Refresh the task modal Source dropdown from state
  const sel = document.getElementById('taskSource');
  if (!sel) return;
  const options = ['<option value="">— None —</option>'];
  state.sourceOptions.forEach(s => {
    options.push(`<option value="${escapeHtml(s.name)}">${escapeHtml(s.name)}</option>`);
  });
  sel.innerHTML = options.join('');
}

// =============================================================
// HELP CENTER — plain-language guide to every feature
// =============================================================
// =============================================================
// ACTIVITY LOG — UI rendering + filtering
// Companion to logActivity() / logTaskEdited() / etc. defined earlier.
// =============================================================

// =============================================================
// ADVANCEMENTS TRACKER — runtime logic
// State lives at state.advancements ([{id,title,description,tier,status,priority,notes,addedAt,implementedAt}])
// Selection set: state.advancementSelectedIds (runtime — used by Send-to-Claude flow)
// =============================================================

let advFormEditingId = null; // when set, the form is editing an existing advancement

// ---- Open / close modal ----
function openAdvancementsModal() {
  document.getElementById('advancementsModal').classList.add('active');
  // Reset filters to defaults on open (less confusing than persisting state)
  // Don't clear search though — it's useful to keep across opens
  renderAdvancements();
  // Scroll to top
  setTimeout(() => {
    const inner = document.querySelector('#advancementsModal .modal');
    if (inner) inner.scrollTop = 0;
  }, 50);
}

function clearAdvancementFilters() {
  document.getElementById('advFilterTier').value = 'all';
  document.getElementById('advFilterStatus').value = 'all';
  document.getElementById('advFilterSearch').value = '';
  // Also reset the favorites-only filter pill so Reset really resets
  state.advFavoritesOnly = false;
  saveState();
  renderAdvancements();
}

// ---- Main render ----
function renderAdvancements() {
  const bodyEl = document.getElementById('advancementsBody');
  const statsEl = document.getElementById('advStats');
  if (!bodyEl) return;

  const list = Array.isArray(state.advancements) ? state.advancements : [];
  const total = list.length;

  // Stats — overall counts
  const counts = { open: 0, 'in-progress': 0, implemented: 0 };
  list.forEach(a => { if (counts[a.status] !== undefined) counts[a.status]++; });
  const pctImplemented = total > 0 ? Math.round((counts.implemented / total) * 100) : 0;

  if (statsEl) {
    statsEl.innerHTML = `
      <div class="adv-stat-row">
        <div class="adv-stat-pill adv-stat-implemented">
          <span class="adv-stat-icon">✅</span>
          <span class="adv-stat-num">${counts.implemented}</span>
          <span class="adv-stat-label">Implemented</span>
        </div>
        <div class="adv-stat-pill adv-stat-progress">
          <span class="adv-stat-icon">⏳</span>
          <span class="adv-stat-num">${counts['in-progress']}</span>
          <span class="adv-stat-label">In Progress</span>
        </div>
        <div class="adv-stat-pill adv-stat-open">
          <span class="adv-stat-icon">⬜</span>
          <span class="adv-stat-num">${counts.open}</span>
          <span class="adv-stat-label">Open</span>
        </div>
        <div class="adv-stat-pill adv-stat-total">
          <span class="adv-stat-num">${total}</span>
          <span class="adv-stat-label">Total</span>
        </div>
      </div>
      <div class="adv-progress-bar">
        <div class="adv-progress-fill" style="width:${pctImplemented}%;"></div>
        <span class="adv-progress-text">${pctImplemented}% implemented</span>
      </div>
    `;
  }

  // Apply filters
  const tierFilter = (document.getElementById('advFilterTier') || {}).value || 'all';
  const statusFilter = (document.getElementById('advFilterStatus') || {}).value || 'all';
  const searchTerm = ((document.getElementById('advFilterSearch') || {}).value || '').trim().toLowerCase();

  let filtered = list.slice();
  if (tierFilter !== 'all') filtered = filtered.filter(a => a.tier === tierFilter);
  if (statusFilter !== 'all') filtered = filtered.filter(a => a.status === statusFilter);
  if (state.advFavoritesOnly) filtered = filtered.filter(a => a.favorite);
  if (searchTerm) {
    filtered = filtered.filter(a => {
      const hay = ((a.title || '') + ' ' + (a.description || '') + ' ' + (a.notes || '')).toLowerCase();
      return hay.includes(searchTerm);
    });
  }

  // Sync the favorites filter button visual state + count chip
  const favBtn = document.getElementById('advFavoritesFilterBtn');
  if (favBtn) {
    favBtn.classList.toggle('active', !!state.advFavoritesOnly);
    favBtn.setAttribute('aria-pressed', state.advFavoritesOnly ? 'true' : 'false');
    const favCount = list.filter(a => a.favorite).length;
    const countEl = favBtn.querySelector('.adv-fav-count');
    if (countEl) countEl.textContent = favCount;
  }

  if (total === 0) {
    bodyEl.innerHTML = `
      <div class="adv-empty">
        <div class="adv-empty-icon">🚀</div>
        <div class="adv-empty-title">No advancements tracked yet</div>
        <div class="adv-empty-msg">Click <strong>+ Add</strong> above to add your first idea, or reload the page to restore the seed list.</div>
      </div>
    `;
    updateAdvBulkToolbar();
    return;
  }

  if (filtered.length === 0) {
    const favHint = state.advFavoritesOnly
      ? `<br><br><em>Tip: the <strong>★ Favorites</strong> filter is on. Click the star button at the top to turn it off, or star some items first.</em>`
      : '';
    bodyEl.innerHTML = `
      <div class="adv-empty">
        <div class="adv-empty-icon">🔍</div>
        <div class="adv-empty-title">No advancements match your filters</div>
        <div class="adv-empty-msg">Try a broader filter or click <strong>↺ Reset</strong> above.${favHint}</div>
      </div>
    `;
    updateAdvBulkToolbar();
    return;
  }

  // Group by tier (preserving the canonical tier order)
  const grouped = {};
  filtered.forEach(a => {
    const tier = a.tier || 'other';
    if (!grouped[tier]) grouped[tier] = [];
    grouped[tier].push(a);
  });

  let html = '';
  ADVANCEMENT_TIERS.forEach(tierMeta => {
    const items = grouped[tierMeta.id];
    if (!items || items.length === 0) return;

    // Compute tier-level progress
    const tierImplemented = items.filter(a => a.status === 'implemented').length;
    const tierTotal = items.length;
    const tierPct = tierTotal > 0 ? Math.round((tierImplemented / tierTotal) * 100) : 0;

    html += `
      <details class="adv-tier-section" open>
        <summary class="adv-tier-summary" style="border-left:4px solid ${tierMeta.color};">
          <span class="adv-tier-icon">${tierMeta.icon}</span>
          <span class="adv-tier-label">${escapeHtml(tierMeta.label)}</span>
          <span class="adv-tier-count">${tierImplemented} / ${tierTotal} implemented</span>
          <span class="adv-tier-bar"><span class="adv-tier-bar-fill" style="width:${tierPct}%;background:${tierMeta.color};"></span></span>
        </summary>
        <div class="adv-tier-body">
          ${items.map(a => renderAdvancementRow(a)).join('')}
        </div>
      </details>
    `;
  });

  bodyEl.innerHTML = html;
  updateAdvBulkToolbar();
}

// Render a single row
function renderAdvancementRow(a) {
  const isSelected = state.advancementSelectedIds.includes(a.id);
  const statusIcons = { open: '⬜', 'in-progress': '⏳', implemented: '✅' };
  const statusLabels = { open: 'Open', 'in-progress': 'In Progress', implemented: 'Implemented' };
  const priorityIcons = { high: '🔥', normal: '●', low: '○' };
  const implementedDate = a.implementedAt
    ? new Date(a.implementedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
    : '';

  return `
    <div class="adv-row${a.status === 'implemented' ? ' adv-implemented' : ''}${isSelected ? ' adv-selected' : ''}${a.favorite ? ' adv-favorited' : ''}" data-id="${a.id}">
      <input type="checkbox" class="adv-row-checkbox" ${isSelected ? 'checked' : ''} onchange="toggleAdvancementSelection('${a.id}')" title="Select for bulk actions">
      <button class="adv-fav-btn" onclick="toggleAdvancementFavorite('${a.id}')" title="${a.favorite ? 'Unfavorite' : 'Favorite (star)'}" aria-pressed="${a.favorite ? 'true' : 'false'}">${a.favorite ? '★' : '☆'}</button>
      <div class="adv-row-content">
        <div class="adv-row-header">
          <span class="adv-row-title">${escapeHtml(a.title || '(untitled)')}</span>
          <span class="adv-row-priority adv-priority-${a.priority || 'normal'}" title="Priority: ${a.priority || 'normal'}">${priorityIcons[a.priority] || '●'}</span>
        </div>
        ${a.description ? `<div class="adv-row-desc">${escapeHtml(a.description)}</div>` : ''}
        ${a.notes ? `<div class="adv-row-notes"><strong>Notes:</strong> ${escapeHtml(a.notes)}</div>` : ''}
        <div class="adv-row-meta">
          <select class="adv-row-status adv-status-${a.status}" onchange="changeAdvancementStatus('${a.id}', this.value)" title="Change status">
            <option value="open"${a.status === 'open' ? ' selected' : ''}>⬜ Open</option>
            <option value="in-progress"${a.status === 'in-progress' ? ' selected' : ''}>⏳ In Progress</option>
            <option value="implemented"${a.status === 'implemented' ? ' selected' : ''}>✅ Implemented</option>
          </select>
          ${implementedDate ? `<span class="adv-row-implemented-date">Done ${escapeHtml(implementedDate)}</span>` : ''}
        </div>
      </div>
      <div class="adv-row-actions">
        <button class="btn btn-sm" onclick="openEditAdvancementForm('${a.id}')" title="Edit this advancement">✎</button>
        <button class="btn btn-sm" style="color:var(--sbg-red);" onclick="deleteAdvancement('${a.id}')" title="Delete this advancement">🗑</button>
      </div>
    </div>
  `;
}

// ---- Selection / bulk toolbar ----
function toggleAdvancementSelection(id) {
  const idx = state.advancementSelectedIds.indexOf(id);
  if (idx === -1) {
    state.advancementSelectedIds.push(id);
  } else {
    state.advancementSelectedIds.splice(idx, 1);
  }
  // Don't re-render the whole list — just update the row + toolbar
  const row = document.querySelector(`.adv-row[data-id="${id}"]`);
  if (row) row.classList.toggle('adv-selected', state.advancementSelectedIds.includes(id));
  updateAdvBulkToolbar();
}

function advClearSelection() {
  state.advancementSelectedIds = [];
  document.querySelectorAll('.adv-row.adv-selected').forEach(r => r.classList.remove('adv-selected'));
  document.querySelectorAll('.adv-row-checkbox:checked').forEach(c => { c.checked = false; });
  updateAdvBulkToolbar();
}

function updateAdvBulkToolbar() {
  const toolbar = document.getElementById('advBulkToolbar');
  const countEl = document.getElementById('advBulkCount');
  if (!toolbar || !countEl) return;
  const n = state.advancementSelectedIds.length;
  if (n === 0) {
    toolbar.style.display = 'none';
  } else {
    toolbar.style.display = 'flex';
    countEl.textContent = `${n} selected`;
  }
}

function advBulkSetStatus(newStatus) {
  if (state.advancementSelectedIds.length === 0) return;
  const ids = new Set(state.advancementSelectedIds);
  const now = Date.now();
  state.advancements.forEach(a => {
    if (ids.has(a.id)) {
      a.status = newStatus;
      a.implementedAt = newStatus === 'implemented' ? now : null;
    }
  });
  saveState();
  renderAdvancements();
}

function advBulkDelete() {
  if (state.advancementSelectedIds.length === 0) return;
  const n = state.advancementSelectedIds.length;
  if (!confirm(`Delete ${n} advancement${n === 1 ? '' : 's'}? This cannot be undone.`)) return;
  const ids = new Set(state.advancementSelectedIds);
  state.advancements = state.advancements.filter(a => !ids.has(a.id));
  state.advancementSelectedIds = [];
  saveState();
  renderAdvancements();
}

// ---- Single-item status / delete ----
function changeAdvancementStatus(id, newStatus) {
  const adv = state.advancements.find(a => a.id === id);
  if (!adv) return;
  adv.status = newStatus;
  adv.implementedAt = newStatus === 'implemented' ? Date.now() : null;
  saveState();
  renderAdvancements();
}

// Toggle the star (favorite) on an advancement. Optimistic — updates the
// row class instantly without re-rendering the whole list, then persists.
function toggleAdvancementFavorite(id) {
  const adv = state.advancements.find(a => a.id === id);
  if (!adv) return;
  adv.favorite = !adv.favorite;
  saveState();
  // Light-touch DOM update so we don't lose scroll position. If the
  // favorites filter is on AND the item just got unfavorited, it should
  // disappear from view — easiest is full re-render in that case.
  if (state.advFavoritesOnly) {
    renderAdvancements();
    return;
  }
  const row = document.querySelector(`.adv-row[data-id="${id}"]`);
  if (!row) return;
  row.classList.toggle('adv-favorited', adv.favorite);
  const btn = row.querySelector('.adv-fav-btn');
  if (btn) {
    btn.textContent = adv.favorite ? '★' : '☆';
    btn.title = adv.favorite ? 'Unfavorite' : 'Favorite (star)';
    btn.setAttribute('aria-pressed', adv.favorite ? 'true' : 'false');
  }
  // Refresh the count chip on the favorites button
  const favBtn = document.getElementById('advFavoritesFilterBtn');
  if (favBtn) {
    const favCount = state.advancements.filter(a => a.favorite).length;
    const countEl = favBtn.querySelector('.adv-fav-count');
    if (countEl) countEl.textContent = favCount;
  }
}

// Toggle the "Favorites only" filter mode (filter pill at the top of the
// advancements modal). Persists.
function toggleAdvancementsFavoritesOnly() {
  state.advFavoritesOnly = !state.advFavoritesOnly;
  saveState();
  renderAdvancements();
}

function deleteAdvancement(id) {
  const adv = state.advancements.find(a => a.id === id);
  if (!adv) return;
  if (!confirm(`Delete advancement?\n\n"${adv.title}"\n\nThis cannot be undone.`)) return;
  state.advancements = state.advancements.filter(a => a.id !== id);
  state.advancementSelectedIds = state.advancementSelectedIds.filter(x => x !== id);
  saveState();
  renderAdvancements();
}

// ---- Add / Edit form ----
function openAddAdvancementForm() {
  advFormEditingId = null;
  document.getElementById('advFormTitle').textContent = 'Add Advancement';
  document.getElementById('advFormName').value = '';
  document.getElementById('advFormDescription').value = '';
  document.getElementById('advFormTier').value = 'other';
  document.getElementById('advFormPriority').value = 'normal';
  document.getElementById('advFormNotes').value = '';
  document.getElementById('advancementFormModal').classList.add('active');
  setTimeout(() => document.getElementById('advFormName').focus(), 100);
}

function openEditAdvancementForm(id) {
  const adv = state.advancements.find(a => a.id === id);
  if (!adv) return;
  advFormEditingId = id;
  document.getElementById('advFormTitle').textContent = 'Edit Advancement';
  document.getElementById('advFormName').value = adv.title || '';
  document.getElementById('advFormDescription').value = adv.description || '';
  document.getElementById('advFormTier').value = adv.tier || 'other';
  document.getElementById('advFormPriority').value = adv.priority || 'normal';
  document.getElementById('advFormNotes').value = adv.notes || '';
  document.getElementById('advancementFormModal').classList.add('active');
  setTimeout(() => document.getElementById('advFormName').focus(), 100);
}

function saveAdvancementFromForm() {
  const title = document.getElementById('advFormName').value.trim();
  if (!title) {
    alert('Title is required.');
    document.getElementById('advFormName').focus();
    return;
  }
  const data = {
    title: title,
    description: document.getElementById('advFormDescription').value.trim(),
    tier: document.getElementById('advFormTier').value,
    priority: document.getElementById('advFormPriority').value,
    notes: document.getElementById('advFormNotes').value.trim()
  };

  if (advFormEditingId) {
    const adv = state.advancements.find(a => a.id === advFormEditingId);
    if (adv) Object.assign(adv, data);
  } else {
    state.advancements.unshift({
      id: 'adv-' + Date.now().toString(36) + '-' + Math.floor(Math.random() * 10000).toString(36),
      ...data,
      status: 'open',
      favorite: false,
      addedAt: Date.now(),
      implementedAt: null
    });
  }
  advFormEditingId = null;
  saveState();
  closeModal('advancementFormModal');
  renderAdvancements();
}

// ---- CSV export ----
function exportAdvancementsCSV() {
  const list = Array.isArray(state.advancements) ? state.advancements : [];
  if (list.length === 0) {
    alert('No advancements to export.');
    return;
  }
  const headers = ['Title', 'Description', 'Tier', 'Status', 'Priority', 'Notes', 'Added', 'Implemented'];
  const tierLabels = {};
  ADVANCEMENT_TIERS.forEach(t => { tierLabels[t.id] = t.label; });

  const rows = list.map(a => [
    a.title || '',
    a.description || '',
    tierLabels[a.tier] || a.tier || '',
    a.status || '',
    a.priority || '',
    a.notes || '',
    a.addedAt ? new Date(a.addedAt).toLocaleDateString('en-US') : '',
    a.implementedAt ? new Date(a.implementedAt).toLocaleDateString('en-US') : ''
  ]);

  const csv = [headers, ...rows].map(row =>
    row.map(cell => {
      const s = String(cell == null ? '' : cell);
      if (/[",\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
      return s;
    }).join(',')
  ).join('\n');

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const filename = `SBG_Advancements_${new Date().toISOString().slice(0, 10)}.csv`;
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 100);
}

// =============================================================
// SEND TO CLAUDE — package selected advancements + HTML for handoff
// =============================================================

function openSendToClaudeModal() {
  if (state.advancementSelectedIds.length === 0) {
    alert('Select at least one advancement first by checking the boxes.');
    return;
  }
  const selected = getSelectedAdvancements();
  if (selected.length === 0) return;

  // Populate the selected list preview
  const listEl = document.getElementById('stcSelectedList');
  if (listEl) {
    listEl.innerHTML = selected.map(a => {
      const tierMeta = ADVANCEMENT_TIERS.find(t => t.id === a.tier) || { icon: '📌', label: 'Other' };
      return `
        <div class="stc-selected-item">
          <span class="stc-tier-icon" title="${escapeHtml(tierMeta.label)}">${tierMeta.icon}</span>
          <span class="stc-title">${escapeHtml(a.title)}</span>
        </div>
      `;
    }).join('');
  }

  // Generate the prompt
  const prompt = buildClaudePrompt(selected);
  document.getElementById('stcPromptText').value = prompt;
  document.getElementById('stcCount').textContent = selected.length;

  // Hide any prior status message
  const statusEl = document.getElementById('stcStatusMsg');
  if (statusEl) statusEl.style.display = 'none';

  document.getElementById('sendToClaudeModal').classList.add('active');
}

function getSelectedAdvancements() {
  const ids = new Set(state.advancementSelectedIds);
  return state.advancements.filter(a => ids.has(a.id));
}

// Build the build-request prompt sent to Claude
function buildClaudePrompt(selected) {
  const tierLabels = {};
  ADVANCEMENT_TIERS.forEach(t => { tierLabels[t.id] = t.label; });

  // Group selected items by tier for cleaner organization
  const grouped = {};
  selected.forEach(a => {
    const tier = a.tier || 'other';
    if (!grouped[tier]) grouped[tier] = [];
    grouped[tier].push(a);
  });

  let body = '';
  ADVANCEMENT_TIERS.forEach(tierMeta => {
    const items = grouped[tierMeta.id];
    if (!items || items.length === 0) return;
    body += `\n## ${tierMeta.label}\n\n`;
    items.forEach((a, i) => {
      body += `${i + 1}. **${a.title}**\n`;
      if (a.description) body += `   ${a.description}\n`;
      if (a.notes) body += `   _Notes:_ ${a.notes}\n`;
      if (a.priority === 'high') body += `   _Priority:_ 🔥 High\n`;
      body += '\n';
    });
  });

  const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  return `Hi Claude — I'd like to add the following advancement${selected.length === 1 ? '' : 's'} to the SBG Precon Bid Tracker.

The current HTML file is attached to this message. Please build the requested feature${selected.length === 1 ? '' : 's'} into the existing single-file structure, preserving all current functionality, brand styling (SBG navy #0a2540, red #c8322b, gold #c07f00), and code conventions (Barlow Condensed / Inter / JetBrains Mono fonts; localStorage key sbg_precon_tracker_v3).

After building, please:
- Verify the JavaScript is clean (no syntax errors)
- Mark the corresponding advancement${selected.length === 1 ? '' : 's'} as Implemented in the in-app Advancements tracker (state.advancements array) so the status reflects the new build
- Run a feature verification check confirming each of the items below is wired in
- Present the updated file via the present_files tool

---

# Build Request — ${dateStr}
${body}
---

Please proceed with the build. Thanks!`;
}

function copyStcPromptOnly() {
  const prompt = document.getElementById('stcPromptText').value;
  copyToClipboardSafe(prompt).then(success => {
    showStcStatus(success
      ? '✓ Prompt copied to clipboard. Paste it into a new Claude.ai chat.'
      : '⚠ Couldn\'t copy automatically — select the prompt text and copy manually (Ctrl+C / Cmd+C).',
      success ? 'success' : 'warn'
    );
  });
}

function executeSendToClaude() {
  const prompt = document.getElementById('stcPromptText').value;
  if (!prompt.trim()) {
    showStcStatus('⚠ Prompt is empty. Add some text before sending.', 'warn');
    return;
  }

  // Step 1: Copy prompt to clipboard
  copyToClipboardSafe(prompt).then(copied => {

    // Step 2: Trigger HTML file download (clone of current page)
    triggerCurrentHtmlDownload();

    // Step 3: Open Claude.ai in a new tab
    setTimeout(() => {
      window.open('https://claude.ai/new', '_blank');
    }, 400);

    // Show success message with next steps
    const msg = copied
      ? '✓ Prompt copied · HTML downloading · Claude.ai opening in new tab.\n\nNext: in the new Claude tab, paste the prompt (Ctrl/Cmd+V) and drag the downloaded HTML file in, then send.'
      : '⚠ Couldn\'t copy automatically. The HTML downloaded and Claude.ai is opening — copy the prompt above manually before pasting.';
    showStcStatus(msg, copied ? 'success' : 'warn');
  });
}

// Trigger a download of the current HTML page so the user can attach it to Claude
function triggerCurrentHtmlDownload() {
  try {
    // Fetch the current page's full HTML (works for static single-file)
    const html = '<!DOCTYPE html>\n' + document.documentElement.outerHTML;
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const ts = new Date().toISOString().slice(0, 10);
    const filename = `SBG_Precon_Tracker_${ts}.html`;
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 200);
  } catch (e) {
    console.error('HTML download failed:', e);
    showStcStatus('⚠ Couldn\'t auto-download the HTML. Save the page manually (Ctrl+S / Cmd+S) and attach to Claude.', 'warn');
  }
}

// Cross-browser clipboard copy with fallback
function copyToClipboardSafe(text) {
  return new Promise((resolve) => {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(
        () => resolve(true),
        () => resolve(fallbackCopy(text))
      );
    } else {
      resolve(fallbackCopy(text));
    }
  });
}

function fallbackCopy(text) {
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  } catch (e) {
    return false;
  }
}

function showStcStatus(msg, kind) {
  const el = document.getElementById('stcStatusMsg');
  if (!el) return;
  el.textContent = msg;
  el.className = 'stc-status-msg stc-status-' + (kind || 'info');
  el.style.display = 'block';
}

function openActivityLogModal() {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) {
    alert('Open a project first — the activity log is project-scoped.');
    return;
  }
  document.getElementById('activityLogModal').classList.add('active');
  // Populate user filter dropdown from log entries
  populateActivityUserFilter(project);
  // Update subtitle with project name
  const sub = document.getElementById('activityLogSubtitle');
  if (sub) {
    const total = Array.isArray(project.activityLog) ? project.activityLog.length : 0;
    sub.textContent = `${escapeHtml(project.name || 'Untitled project')} — ${total} event${total === 1 ? '' : 's'} on file.`;
  }
  renderActivityLog();
  // Scroll modal to top
  setTimeout(() => {
    const modalInner = document.querySelector('#activityLogModal .modal');
    if (modalInner) modalInner.scrollTop = 0;
  }, 50);
}

function populateActivityUserFilter(project) {
  const sel = document.getElementById('activityFilterUser');
  if (!sel) return;
  const log = Array.isArray(project.activityLog) ? project.activityLog : [];
  // Collect unique actors
  const users = new Set();
  log.forEach(e => { if (e.actor) users.add(e.actor); });
  const sorted = Array.from(users).sort();
  // Preserve current selection
  const current = sel.value;
  sel.innerHTML = '<option value="all">All users</option>' +
    sorted.map(u => `<option value="${escapeHtml(u)}">${escapeHtml(u)}</option>`).join('');
  // Restore selection if still valid
  if (current && (current === 'all' || sorted.includes(current))) {
    sel.value = current;
  }
}

function clearActivityFilters() {
  document.getElementById('activityFilterType').value = 'all';
  document.getElementById('activityFilterAction').value = 'all';
  document.getElementById('activityFilterUser').value = 'all';
  document.getElementById('activityFilterSearch').value = '';
  renderActivityLog();
}

// Returns the filtered + reverse-chronological entries for the active project
function getFilteredActivityEntries() {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project || !Array.isArray(project.activityLog)) return [];

  const filterType = (document.getElementById('activityFilterType') || {}).value || 'all';
  const filterAction = (document.getElementById('activityFilterAction') || {}).value || 'all';
  const filterUser = (document.getElementById('activityFilterUser') || {}).value || 'all';
  const filterSearch = ((document.getElementById('activityFilterSearch') || {}).value || '').trim().toLowerCase();

  return project.activityLog
    .filter(e => {
      if (filterType !== 'all' && e.type !== filterType) return false;
      if (filterAction !== 'all' && e.action !== filterAction) return false;
      if (filterUser !== 'all' && e.actor !== filterUser) return false;
      if (filterSearch) {
        const haystack = [
          e.summary || '',
          e.taskTitle || '',
          e.actor || '',
          (e.changes || []).map(c => `${c.field} ${c.from} ${c.to}`).join(' ')
        ].join(' ').toLowerCase();
        if (!haystack.includes(filterSearch)) return false;
      }
      return true;
    })
    .slice() // copy before sorting (don't mutate the source)
    .sort((a, b) => b.timestamp - a.timestamp); // newest first
}

function renderActivityLog() {
  const project = state.projects.find(p => p.id === state.activeProjectId);

  // ----- Inline section (collapsible in project view) -----
  // Has its own simpler filter set and renders independently.
  renderInlineActivityLog(project);

  // ----- Full modal (only renders when modal is in DOM) -----
  const body = document.getElementById('activityLogBody');
  const stats = document.getElementById('activityLogStats');
  if (!body) return;

  if (!project) {
    body.innerHTML = '<div class="al-empty">No active project.</div>';
    if (stats) stats.innerHTML = '';
    return;
  }

  const filtered = getFilteredActivityEntries();
  const total = Array.isArray(project.activityLog) ? project.activityLog.length : 0;

  // Stats line
  if (stats) {
    if (total === 0) {
      stats.innerHTML = '';
    } else if (filtered.length === total) {
      stats.innerHTML = `<span class="al-stat">Showing all ${total} event${total === 1 ? '' : 's'}</span>`;
    } else {
      stats.innerHTML = `<span class="al-stat">Showing ${filtered.length} of ${total} event${total === 1 ? '' : 's'} (filtered)</span>`;
    }
  }

  if (total === 0) {
    body.innerHTML = `
      <div class="al-empty">
        <div class="al-empty-icon">📜</div>
        <div class="al-empty-title">No activity yet</div>
        <div class="al-empty-msg">Edit any task, sign off a completion, or update a milestone — the activity log will start filling in automatically.</div>
      </div>`;
    return;
  }

  if (filtered.length === 0) {
    body.innerHTML = `
      <div class="al-empty">
        <div class="al-empty-icon">🔍</div>
        <div class="al-empty-title">No events match your filters</div>
        <div class="al-empty-msg">Try a broader filter or click Reset above.</div>
      </div>`;
    return;
  }

  // Group entries by date for visual organization
  const groups = groupActivityByDate(filtered);
  let html = '';
  groups.forEach(group => {
    html += `<div class="al-date-divider"><span>${escapeHtml(group.label)}</span></div>`;
    group.entries.forEach(e => {
      html += renderActivityEntry(e);
    });
  });

  body.innerHTML = html;
}

// Renders the inline collapsible activity-log section in the project view.
// Uses simpler filters than the full modal (no date grouping, no search).
// Safe no-op when the inline section isn't in the DOM.
function renderInlineActivityLog(project) {
  const listEl = document.getElementById('activityLogList');
  if (!listEl || !project) return;
  const summaryCountEl = document.getElementById('alSummaryCount');
  const typeFilterEl = document.getElementById('activityLogFilter');
  const actorFilterEl = document.getElementById('activityLogActorFilter');

  const log = Array.isArray(project.activityLog) ? project.activityLog : [];
  const total = log.length;

  if (summaryCountEl) {
    summaryCountEl.innerHTML = total > 0
      ? `<strong>${total}</strong> event${total === 1 ? '' : 's'}`
      : 'No activity yet';
  }

  // Populate actor filter dropdown — preserve current selection
  if (actorFilterEl) {
    const currentValue = actorFilterEl.value;
    const actors = new Set();
    log.forEach(e => { if (e.actor) actors.add(e.actor); });
    const sortedActors = Array.from(actors).sort();
    actorFilterEl.innerHTML = '<option value="all">All Users</option>' +
      sortedActors.map(a => `<option value="${escapeHtml(a)}"${a === currentValue ? ' selected' : ''}>${escapeHtml(a)}</option>`).join('');
  }

  if (total === 0) {
    listEl.innerHTML = `<div class="al-empty">No activity logged yet for this project. Changes will appear here as you work.</div>`;
    return;
  }

  // Apply inline filters
  const typeFilter = typeFilterEl ? typeFilterEl.value : 'all';
  const actorFilter = actorFilterEl ? actorFilterEl.value : 'all';

  let filtered = log.slice();
  if (typeFilter !== 'all') {
    const knownActions = ['status-changed', 'signed-off', 'rejected', 'created', 'edited', 'deleted'];
    if (knownActions.includes(typeFilter)) {
      filtered = filtered.filter(e => e.action === typeFilter);
    } else {
      filtered = filtered.filter(e => e.type === typeFilter);
    }
  }
  if (actorFilter !== 'all') {
    filtered = filtered.filter(e => e.actor === actorFilter);
  }
  filtered.sort((a, b) => b.timestamp - a.timestamp);

  // Cap inline display — keep it lightweight; full log lives in the modal
  const INLINE_LIMIT = 25;
  const displayed = filtered.slice(0, INLINE_LIMIT);

  if (displayed.length === 0) {
    listEl.innerHTML = `<div class="al-empty">No events match the current filters.</div>`;
    return;
  }

  let html = displayed.map(e => renderActivityEntry(e)).join('');
  if (filtered.length > INLINE_LIMIT) {
    html += `<div class="al-truncate-note">Showing ${INLINE_LIMIT} of ${filtered.length}. <a href="#" onclick="event.preventDefault();openActivityLogModal();">Open full Activity Log →</a></div>`;
  }
  listEl.innerHTML = html;
}

// Groups entries by day, returning array of {label, entries[]}.
// Labels: "Today", "Yesterday", or "Mon, Apr 21".
function groupActivityByDate(entries) {
  const groups = [];
  const groupMap = new Map();

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);

  entries.forEach(e => {
    const d = new Date(e.timestamp);
    const dayKey = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    let label;
    const entryDay = new Date(d);
    entryDay.setHours(0, 0, 0, 0);
    if (entryDay.getTime() === today.getTime()) {
      label = 'Today';
    } else if (entryDay.getTime() === yesterday.getTime()) {
      label = 'Yesterday';
    } else {
      label = d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: d.getFullYear() === today.getFullYear() ? undefined : 'numeric' });
    }
    if (!groupMap.has(dayKey)) {
      const group = { label, entries: [] };
      groups.push(group);
      groupMap.set(dayKey, group);
    }
    groupMap.get(dayKey).entries.push(e);
  });

  return groups;
}

// Renders a single activity entry as an HTML row.
function renderActivityEntry(e) {
  const icon = getActivityIcon(e);
  const time = new Date(e.timestamp).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
  const tooltip = formatAbsoluteTime(e.timestamp);
  const actionClass = `al-action-${(e.action || 'edited').replace(/[^a-z-]/gi, '')}`;
  const typeClass = `al-type-${(e.type || 'task').replace(/[^a-z]/gi, '')}`;

  // Build change details (Medium-tier verbosity — show field-level diffs)
  let changesHtml = '';
  if (Array.isArray(e.changes) && e.changes.length > 0) {
    changesHtml = '<div class="al-changes">' +
      e.changes.map(c => {
        const fromVal = formatActivityValue(c.field, c.from);
        const toVal = formatActivityValue(c.field, c.to);
        return `
          <div class="al-change-row">
            <span class="al-change-field">${escapeHtml(c.field)}:</span>
            <span class="al-change-from">${fromVal || '<em>(empty)</em>'}</span>
            <span class="al-change-arrow">→</span>
            <span class="al-change-to">${toVal || '<em>(empty)</em>'}</span>
          </div>`;
      }).join('') +
      '</div>';
  } else if (e.fieldName && (e.oldValue !== undefined || e.newValue !== undefined)) {
    // Single-field events (e.g., status change)
    const fromVal = formatActivityValue(e.fieldName, e.oldValue);
    const toVal = formatActivityValue(e.fieldName, e.newValue);
    changesHtml = `
      <div class="al-changes">
        <div class="al-change-row">
          <span class="al-change-field">${escapeHtml(humanizeFieldName(e.fieldName))}:</span>
          <span class="al-change-from">${fromVal || '<em>(empty)</em>'}</span>
          <span class="al-change-arrow">→</span>
          <span class="al-change-to">${toVal || '<em>(empty)</em>'}</span>
        </div>
      </div>`;
  }

  // "Open task" link if entry references a task
  let openTaskBtn = '';
  if (e.taskId && e.action !== 'deleted') {
    openTaskBtn = `<button class="al-open-task-btn" onclick="openTaskFromActivityLog('${e.taskId}')" title="Open task in modal">↗</button>`;
  }

  return `
    <div class="al-entry ${typeClass} ${actionClass}">
      <div class="al-entry-icon">${icon}</div>
      <div class="al-entry-content">
        <div class="al-entry-header">
          <span class="al-entry-summary">${escapeHtml(e.summary || '(no summary)')}</span>
          ${openTaskBtn}
        </div>
        <div class="al-entry-meta">
          <span class="al-entry-actor" title="Actor">${escapeHtml(e.actor || 'Unknown')}</span>
          <span class="al-entry-time" title="${escapeHtml(tooltip)}">${escapeHtml(time)}</span>
        </div>
        ${changesHtml}
      </div>
    </div>`;
}

// Format a value for display in the activity log.
// Handles dates, statuses, and other special-case fields.
function formatActivityValue(field, value) {
  if (value === undefined || value === null || value === '') return '';
  const lowerField = (field || '').toLowerCase();

  // Date fields — try to format as "Apr 21"
  if (lowerField.includes('date')) {
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      return escapeHtml(formatDate(value));
    }
  }

  // Status: friendly labels
  if (lowerField === 'status') {
    const statusLabels = {
      'not-started': 'Not Started',
      'in-progress': 'In Progress',
      'blocked': 'Blocked',
      'pending': 'Pending',
      'done': 'Complete'
    };
    return escapeHtml(statusLabels[value] || value);
  }

  // Notes — don't dump full text, just say "(updated)"
  if (lowerField === 'notes') {
    return '<em>(text changed)</em>';
  }

  // Truncate very long values
  let str = String(value);
  if (str.length > 80) str = str.substring(0, 77) + '…';
  return escapeHtml(str);
}

// Convert internal field names like 'dueDate' to 'Due Date'
function humanizeFieldName(field) {
  if (!field) return '';
  // Special cases
  const map = {
    'dueDate': 'Due Date',
    'startDate': 'Start Date',
    'ballInCourt': 'Ball in Court',
    'leadEstimator': 'Lead Estimator',
    'dayOffset': 'Day Offset'
  };
  if (map[field]) return map[field];
  // Generic camelCase → Title Case
  return field
    .replace(/([A-Z])/g, ' $1')
    .replace(/^./, c => c.toUpperCase())
    .trim();
}

// Open the task that this activity entry refers to.
// If the task no longer exists (e.g., deleted later), shows a friendly notice.
function openTaskFromActivityLog(taskId) {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) return;
  const task = project.tasks.find(t => t.id === taskId);
  if (!task) {
    alert('That task is no longer in this project. It may have been deleted after this activity was logged.');
    return;
  }
  closeModal('activityLogModal');
  setTimeout(() => openTaskModal(null, taskId), 100);
}

// Permanently clear the active project's activity log
function clearProjectActivityLog() {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) return;
  const total = Array.isArray(project.activityLog) ? project.activityLog.length : 0;
  if (total === 0) {
    alert('The activity log is already empty.');
    return;
  }
  if (!confirm(`Permanently delete all ${total} activity log entries for "${project.name || 'this project'}"?\n\nThis cannot be undone.\n\nNote: The log will continue capturing new events going forward — only past entries are cleared.`)) return;
  project.activityLog = [];
  saveState();
  renderActivityLog();
  // Refresh subtitle
  const sub = document.getElementById('activityLogSubtitle');
  if (sub) {
    sub.textContent = `${escapeHtml(project.name || 'Untitled project')} — 0 events on file.`;
  }
}

// Export the filtered activity log as CSV
function exportActivityLogCSV() {
  const project = state.projects.find(p => p.id === state.activeProjectId);
  if (!project) return;
  const entries = getFilteredActivityEntries();
  if (entries.length === 0) {
    alert('No entries to export — adjust your filters or wait for activity to accumulate.');
    return;
  }

  // Build CSV
  const headers = ['Timestamp', 'Actor', 'Type', 'Action', 'Task / Subject', 'Field', 'From', 'To', 'Summary'];
  const rows = [];

  entries.forEach(e => {
    const ts = new Date(e.timestamp).toLocaleString('en-US');
    const subject = e.taskTitle || e.milestoneName || (e.addendumNumber ? `Addendum #${e.addendumNumber}` : '') || '';

    if (Array.isArray(e.changes) && e.changes.length > 0) {
      e.changes.forEach(c => {
        rows.push([ts, e.actor, e.type, e.action, subject, c.field, c.from, c.to, e.summary]);
      });
    } else if (e.fieldName) {
      rows.push([ts, e.actor, e.type, e.action, subject, humanizeFieldName(e.fieldName), e.oldValue || '', e.newValue || '', e.summary]);
    } else {
      rows.push([ts, e.actor, e.type, e.action, subject, '', '', '', e.summary]);
    }
  });

  const csv = [headers, ...rows]
    .map(row => row.map(cell => {
      const s = String(cell == null ? '' : cell);
      // CSV-quote if contains comma, quote, or newline
      if (/[",\n]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
      return s;
    }).join(','))
    .join('\n');

  // Trigger download
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const projectSlug = (project.name || 'project').replace(/[^a-z0-9]+/gi, '-').toLowerCase();
  const dateSlug = new Date().toISOString().slice(0, 10);
  a.href = url;
  a.download = `activity-log-${projectSlug}-${dateSlug}.csv`;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, 100);
}

function openHelpModal() {
  document.getElementById('helpModal').classList.add('active');
  // Reset search field
  const searchEl = document.getElementById('helpSearch');
  if (searchEl) {
    searchEl.value = '';
    filterHelpSections('');
  }
  // Scroll modal to top
  setTimeout(() => {
    const modalInner = document.querySelector('#helpModal .modal');
    if (modalInner) modalInner.scrollTop = 0;
    if (searchEl) searchEl.focus();
  }, 50);
}

function expandAllHelpSections() {
  document.querySelectorAll('#helpModal .help-section').forEach(s => s.open = true);
}

function collapseAllHelpSections() {
  document.querySelectorAll('#helpModal .help-section').forEach(s => s.open = false);
}

// Filter help sections by search query — matches keywords + visible text content.
// Empty query restores normal display (sections collapsed except the first one).
function filterHelpSections(query) {
  const q = (query || '').trim().toLowerCase();
  const sections = document.querySelectorAll('#helpModal .help-section');
  if (!q) {
    sections.forEach((s, i) => {
      s.style.display = '';
      // Restore default open state (only Quick Start is open by default)
      s.open = i === 0;
    });
    return;
  }
  sections.forEach(s => {
    const keywords = (s.dataset.helpKeywords || '').toLowerCase();
    const summary = (s.querySelector('summary')?.textContent || '').toLowerCase();
    const body = (s.querySelector('.help-body')?.textContent || '').toLowerCase();
    const matches = keywords.includes(q) || summary.includes(q) || body.includes(q);
    s.style.display = matches ? '' : 'none';
    if (matches) s.open = true;
  });
}

function openSourceModal() {
  document.getElementById('srcNewName').value = '';
  document.getElementById('srcNewIcon').value = '';
  renderSourceList();
  document.getElementById('sourceModal').classList.add('active');
}

// As the user types a new source name, auto-fill the icon field with a smart suggestion.
function suggestNewSourceIcon() {
  const nameEl = document.getElementById('srcNewName');
  const iconEl = document.getElementById('srcNewIcon');
  if (!nameEl || !iconEl) return;
  // Only auto-fill if the icon field is empty (don't overwrite a user's manual choice)
  if (iconEl.value.trim()) return;
  const suggested = suggestSourceIcon(nameEl.value);
  // Use placeholder so user can see the suggestion without filling the input
  iconEl.placeholder = suggested;
}

function addSourceOption() {
  const name = document.getElementById('srcNewName').value.trim();
  if (!name) { alert('Enter a source name'); return; }
  if (state.sourceOptions.some(s => s.name.toLowerCase() === name.toLowerCase())) {
    alert('That source already exists'); return;
  }
  const iconInput = document.getElementById('srcNewIcon').value.trim();
  const icon = iconInput || suggestSourceIcon(name);
  state.sourceOptions.push({ name, icon, photo: null });
  saveState();
  document.getElementById('srcNewName').value = '';
  document.getElementById('srcNewIcon').value = '';
  document.getElementById('srcNewIcon').placeholder = '📥';
  renderSourceList();
  populateSourceSelect();
  render();
}

function removeSourceOption(index) {
  const opt = state.sourceOptions[index];
  if (!opt) return;
  let usage = 0;
  state.projects.forEach(p => p.tasks.forEach(t => { if (t.source === opt.name) usage++; }));
  state.masterTasks.forEach(t => { if (t.source === opt.name) usage++; });
  const msg = usage > 0
    ? `Remove "${opt.name}" from the Source list? ${usage} task(s) currently use it — they will keep the label but it won't appear as a preset option for new tasks.`
    : `Remove "${opt.name}" from the list?`;
  if (!confirm(msg)) return;
  state.sourceOptions.splice(index, 1);
  saveState();
  renderSourceList();
  populateSourceSelect();
  render();
}

function updateSourceName(index, newName) {
  const opt = state.sourceOptions[index];
  if (!opt) return;
  const trimmed = (newName || '').trim();
  if (!trimmed) return;
  const oldName = opt.name;
  if (oldName === trimmed) return;
  // Propagate rename to every task using the old name
  state.projects.forEach(p => p.tasks.forEach(t => {
    if (t.source === oldName) t.source = trimmed;
  }));
  state.masterTasks.forEach(t => { if (t.source === oldName) t.source = trimmed; });
  opt.name = trimmed;
  saveState();
  populateSourceSelect();
  render();
}

// Update just the icon of a source (does not affect tasks since they reference by name)
function updateSourceIcon(index, newIcon) {
  const opt = state.sourceOptions[index];
  if (!opt) return;
  opt.icon = (newIcon || '').trim() || suggestSourceIcon(opt.name);
  saveState();
  renderSourceList();
  render();
}

// Handle photo upload for a source — reads file, downscales to 100x100 for storage efficiency
function handleSourcePhotoUpload(event, index) {
  const opt = state.sourceOptions[index];
  if (!opt) return;
  const file = event.target.files[0];
  if (!file) return;
  if (!file.type.startsWith('image/')) { alert('Please upload an image file'); return; }
  if (file.size > 8 * 1024 * 1024) { alert('Image is too large. Keep it under 8 MB.'); return; }

  const reader = new FileReader();
  reader.onload = e => {
    const img = new Image();
    img.onload = () => {
      // Downscale to 100x100 — small enough for inline rendering everywhere
      const size = 100;
      const canvas = document.createElement('canvas');
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext('2d');
      // White-fill background so transparent PNGs render predictably on dark/light themes
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(0, 0, size, size);
      // Center fit (preserve aspect ratio with letterboxing)
      const ratio = Math.min(size / img.width, size / img.height);
      const dw = img.width * ratio;
      const dh = img.height * ratio;
      const dx = (size - dw) / 2;
      const dy = (size - dh) / 2;
      ctx.drawImage(img, dx, dy, dw, dh);
      const dataUrl = canvas.toDataURL('image/png', 0.92);
      opt.photo = dataUrl;
      saveState();
      renderSourceList();
      render();
    };
    img.onerror = () => alert('Could not read that image file');
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
  // Reset the input so picking the same file again retriggers
  event.target.value = '';
}

function clearSourcePhoto(index) {
  const opt = state.sourceOptions[index];
  if (!opt) return;
  if (!confirm(`Remove uploaded image for "${opt.name}"? The emoji icon will be used instead.`)) return;
  opt.photo = null;
  saveState();
  renderSourceList();
  render();
}

function sortSourceOptions() {
  state.sourceOptions.sort((a,b) => a.name.localeCompare(b.name));
  saveState();
  renderSourceList();
  populateSourceSelect();
}

function resetSourceOptions() {
  if (!confirm('Reset the Source list to the default 10 options? Your customizations (including any uploaded logos) will be lost.')) return;
  state.sourceOptions = getDefaultSourceOptions();
  saveState();
  renderSourceList();
  populateSourceSelect();
  render();
}

function renderSourceList() {
  const list = document.getElementById('sourceList');
  if (state.sourceOptions.length === 0) {
    list.innerHTML = '<div style="padding:30px;text-align:center;color:var(--text-faint);font-style:italic;">No sources defined. Add one above or click Reset.</div>';
    return;
  }
  // Header row
  const header = `
    <div class="src-row src-header-row">
      <div></div>
      <div style="font-family:'Barlow Condensed',sans-serif;font-size:9px;text-transform:uppercase;letter-spacing:0.1em;font-weight:700;color:var(--text-dim);">Icon / Logo</div>
      <div style="font-family:'Barlow Condensed',sans-serif;font-size:9px;text-transform:uppercase;letter-spacing:0.1em;font-weight:700;color:var(--text-dim);">Name</div>
      <div></div>
    </div>
  `;
  list.innerHTML = header + state.sourceOptions.map((opt, i) => {
    // Visual preview: photo if uploaded, else emoji icon
    const visualPreview = opt.photo
      ? `<img src="${opt.photo}" alt="" class="src-preview-img">`
      : `<span class="src-preview-icon">${escapeHtml(opt.icon || '📥')}</span>`;
    return `
      <div class="src-row">
        <div class="src-row-num">${i + 1}</div>
        <div class="src-icon-cell">
          <div class="src-icon-preview">${visualPreview}</div>
          <input type="text" class="src-icon-input" value="${escapeHtml(opt.icon || '')}" maxlength="2" onchange="updateSourceIcon(${i}, this.value)" placeholder="${escapeHtml(suggestSourceIcon(opt.name))}" title="Edit emoji icon">
          <div class="src-photo-actions">
            <button class="btn btn-sm src-photo-btn" onclick="document.getElementById('srcPhoto_${i}').click()" title="${opt.photo ? 'Replace logo' : 'Upload custom logo'}">${opt.photo ? '🔄' : '📷'}</button>
            <input type="file" id="srcPhoto_${i}" accept="image/*" style="display:none" onchange="handleSourcePhotoUpload(event, ${i})">
            ${opt.photo ? `<button class="btn btn-sm src-photo-clear-btn" onclick="clearSourcePhoto(${i})" title="Remove logo, restore emoji">✕</button>` : ''}
          </div>
        </div>
        <input type="text" class="src-name-input" value="${escapeHtml(opt.name)}" onchange="updateSourceName(${i}, this.value)">
        <button class="mtt-remove-btn" onclick="removeSourceOption(${i})" title="Remove source">✕</button>
      </div>
    `;
  }).join('');
}

// =============================================================
// BALL IN COURT MANAGER
// =============================================================
function getDefaultBallInCourtOptions() {
  return [
    { name: 'Lead', color: 'red' },
    { name: 'Support', color: 'blue' },
    { name: 'Owner', color: 'yellow' },
    { name: 'Architect', color: 'yellow' },
    { name: 'Engineer', color: 'yellow' },
    { name: 'Subcontractor', color: 'purple' },
    { name: 'Vendor', color: 'purple' },
    { name: 'GC / CM', color: 'gray' },
    { name: 'Internal Review', color: 'gray' },
    { name: 'Other', color: 'gray' }
  ];
}

function populateBICSelect() {
  const sel = document.getElementById('taskBallInCourt');
  if (!sel) return;
  const options = ['<option value="">— None —</option>'];
  state.ballInCourtOptions.forEach(opt => {
    options.push(`<option value="${escapeHtml(opt.name)}">${escapeHtml(opt.name)}</option>`);
  });
  sel.innerHTML = options.join('');
}

function bicColorFor(name) {
  // Prefer the master list's color; fall back to name-based heuristic for legacy values
  const match = state.ballInCourtOptions.find(o => o.name === name);
  if (match) return match.color;
  // Legacy fallback mapping
  const n = (name || '').toLowerCase();
  if (n.includes('lead')) return 'red';
  if (n.includes('support')) return 'blue';
  if (n.includes('owner') || n.includes('architect') || n.includes('engineer')) return 'yellow';
  if (n.includes('sub') || n.includes('vendor') || n.includes('supplier')) return 'purple';
  return 'gray';
}

function openBICModal() {
  document.getElementById('bicNewName').value = '';
  document.getElementById('bicNewColor').value = 'yellow';
  renderBICList();
  document.getElementById('bicModal').classList.add('active');
}

function addBallInCourtOption() {
  const name = document.getElementById('bicNewName').value.trim();
  const color = document.getElementById('bicNewColor').value;
  if (!name) { alert('Enter a role name'); return; }
  if (state.ballInCourtOptions.some(o => o.name.toLowerCase() === name.toLowerCase())) {
    alert('That role already exists'); return;
  }
  state.ballInCourtOptions.push({ name, color });
  saveState();
  document.getElementById('bicNewName').value = '';
  renderBICList();
  render();
}

function removeBallInCourtOption(index) {
  const opt = state.ballInCourtOptions[index];
  if (!opt) return;
  let usage = 0;
  state.projects.forEach(p => p.tasks.forEach(t => {
    if (t.ballInCourt === opt.name) usage++;
  }));
  const msg = usage > 0
    ? `Remove "${opt.name}" from the Ball in Court list? ${usage} task(s) currently use this role — they will keep the label but won't appear as a preset option for new tasks.`
    : `Remove "${opt.name}" from the list?`;
  if (!confirm(msg)) return;
  state.ballInCourtOptions.splice(index, 1);
  saveState();
  renderBICList();
  render();
}

function updateBICField(index, field, value) {
  const opt = state.ballInCourtOptions[index];
  if (!opt) return;
  if (field === 'name') {
    const newName = value.trim();
    if (!newName) return;
    // Propagate the rename to all existing tasks
    const oldName = opt.name;
    if (oldName !== newName) {
      state.projects.forEach(p => p.tasks.forEach(t => {
        if (t.ballInCourt === oldName) t.ballInCourt = newName;
      }));
    }
    opt.name = newName;
  } else {
    opt[field] = value;
  }
  saveState();
  render();
}

function resetBallInCourtOptions() {
  if (!confirm('Reset the Ball in Court list to the default 10 roles? Your customizations will be lost.')) return;
  state.ballInCourtOptions = getDefaultBallInCourtOptions();
  saveState();
  renderBICList();
  render();
}

function renderBICList() {
  const list = document.getElementById('bicList');
  if (state.ballInCourtOptions.length === 0) {
    list.innerHTML = '<div style="padding:30px;text-align:center;color:var(--text-faint);font-style:italic;">No Ball in Court roles defined. Add one above or click Reset.</div>';
    return;
  }
  const colorOpts = [
    { value: 'red', label: 'Red' },
    { value: 'blue', label: 'Blue' },
    { value: 'yellow', label: 'Yellow' },
    { value: 'purple', label: 'Purple' },
    { value: 'gray', label: 'Gray' },
    { value: 'green', label: 'Green' }
  ];
  list.innerHTML = state.ballInCourtOptions.map((opt, i) => {
    const selectHtml = colorOpts.map(c => `<option value="${c.value}" ${c.value===opt.color?'selected':''}>${c.label}</option>`).join('');
    return `
      <div style="display:grid;grid-template-columns:auto 1fr 160px auto;gap:8px;align-items:center;padding:8px 12px;border-bottom:1px solid var(--border);background:var(--surface);">
        <span class="bic-chip bic-color-${opt.color}">${escapeHtml(opt.name)}</span>
        <input type="text" value="${escapeHtml(opt.name)}" onchange="updateBICField(${i}, 'name', this.value)" style="padding:5px 8px;font-size:12px;">
        <select onchange="updateBICField(${i}, 'color', this.value); renderBICList();" style="padding:5px 8px;font-size:12px;">${selectHtml}</select>
        <button class="mtt-remove-btn" onclick="removeBallInCourtOption(${i})" title="Remove">✕</button>
      </div>
    `;
  }).join('');
}

// =============================================================
// TABLE COLUMN SORTING
// =============================================================
function setTableSort(col) {
  if (state.tableSort.col === col) {
    // Toggle direction, or clear if toggling through
    state.tableSort.dir = state.tableSort.dir === 'asc' ? 'desc' : 'asc';
  } else {
    state.tableSort = { col, dir: 'asc' };
  }
  saveState();
  render();
}

function sortTasksByColumn(tasks, col, dir) {
  const mult = dir === 'desc' ? -1 : 1;
  const cmp = (a, b) => {
    let av, bv;
    switch (col) {
      case 'status':
        const statusOrder = {'blocked':0,'in-progress':1,'pending':2,'not-started':3,'done':4};
        av = statusOrder[a.status] ?? 99; bv = statusOrder[b.status] ?? 99; break;
      case 'task': av = (a.title||'').toLowerCase(); bv = (b.title||'').toLowerCase(); break;
      case 'stage':
        const stageIndex = {};
        STAGES.forEach((s,i) => stageIndex[s.id] = i);
        av = stageIndex[a.stage] ?? 99; bv = stageIndex[b.stage] ?? 99; break;
      case 'assignee': av = (a.assignee||'zzz').toLowerCase(); bv = (b.assignee||'zzz').toLowerCase(); break;
      case 'support': av = (a.support||'zzz').toLowerCase(); bv = (b.support||'zzz').toLowerCase(); break;
      case 'bic': av = (a.ballInCourt||'zzz').toLowerCase(); bv = (b.ballInCourt||'zzz').toLowerCase(); break;
      case 'priority':
        // Critical-first sort: critical tasks (true) sort before non-critical (false)
        av = a.critical ? 0 : 1; bv = b.critical ? 0 : 1; break;
      case 'due':
        av = a.dueDate ? new Date(a.dueDate+'T00:00:00').getTime() : Infinity;
        bv = b.dueDate ? new Date(b.dueDate+'T00:00:00').getTime() : Infinity;
        break;
      case 'hours':
        av = (typeof a.estimatedHours === 'number' && a.estimatedHours > 0) ? a.estimatedHours : Infinity;
        bv = (typeof b.estimatedHours === 'number' && b.estimatedHours > 0) ? b.estimatedHours : Infinity;
        break;
      case 'offset':
        av = typeof a.dayOffset === 'number' ? a.dayOffset : Infinity;
        bv = typeof b.dayOffset === 'number' ? b.dayOffset : Infinity;
        break;
      case 'source': av = (a.source||'zzz').toLowerCase(); bv = (b.source||'zzz').toLowerCase(); break;
      case 'category': av = (a.category||'').toLowerCase(); bv = (b.category||'').toLowerCase(); break;
      case 'notes': av = (a.notes||'').toLowerCase(); bv = (b.notes||'').toLowerCase(); break;
      default: return 0;
    }
    if (av < bv) return -1 * mult;
    if (av > bv) return 1 * mult;
    return 0;
  };
  return tasks.slice().sort(cmp);
}

