function handleCompanyLogoUpload(event) {
  const file = event.target.files[0];
  if (!file) return;
  if (!file.type.startsWith('image/')) { alert('Please upload an image file'); return; }
  if (file.size > 8 * 1024 * 1024) { alert('Image is too large. Keep it under 8 MB.'); return; }

  const reader = new FileReader();
  reader.onload = e => {
    const img = new Image();
    img.onload = () => {
      // Fit into 256x256 canvas while preserving aspect ratio
      const maxDim = 256;
      const scale = Math.min(maxDim / img.width, maxDim / img.height, 1);
      const w = Math.round(img.width * scale);
      const h = Math.round(img.height * scale);
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      const dataUrl = canvas.toDataURL('image/png');
      state.companyLogo = dataUrl;
      saveState();
      renderSettingsLogoPreview();
      renderCompanyLogo();
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
  event.target.value = '';
}
function resetCompanyLogo() {
  if (!confirm('Reset to the default SBG logo?')) return;
  state.companyLogo = null;
  saveState();
  renderSettingsLogoPreview();
  renderCompanyLogo();
}
function renderCompanyLogo() {
  const container = document.getElementById('brandLogo');
  if (!container) return;
  if (state.companyLogo) {
    container.innerHTML = `<img src="${state.companyLogo}" alt="Company Logo" style="width:100%;height:100%;object-fit:contain;border-radius:4px;background:#fff;">`;
  } else {
    container.innerHTML = `
      <svg viewBox="0 0 40 40" xmlns="http://www.w3.org/2000/svg" id="brandLogoSvg">
        <rect x="0" y="0" width="40" height="40" rx="3" fill="#ffffff"/>
        <text x="8" y="29" font-family="Barlow Condensed, sans-serif" font-size="24" font-weight="800" fill="#0a2540" letter-spacing="-1">SBG</text>
        <path d="M 19 10 A 8 8 0 0 1 27 18" stroke="#c8322b" stroke-width="2.5" fill="none" stroke-linecap="round"/>
      </svg>
    `;
  }
}

// =============================================================
// ONBOARDING TOUR — interactive walkthrough for first-time users
// =============================================================
// Tour steps. Each step = {
//   title, body (HTML allowed),
//   selector (CSS selector for spotlight target — null = centered modal-style),
//   placement (auto|top|bottom|left|right),
//   onEnter (optional fn to prepare the UI before showing this step),
//   waitFor (optional ms delay after onEnter to allow DOM updates)
// }
// Steps are filtered at runtime — any whose target doesn't exist gets skipped
// rather than breaking the tour.
// -------------------------------------------------------------------------
// TOUR_STEPS — ordered list of spotlight stops
//
// Each step optionally has a `before` hook that runs right before the step
// is shown. Use this to expand a collapsed section, switch views, or scroll
// content into place so the spotlight has something to land on. Hooks run
// synchronously; if they need DOM settle time they can return a delay (ms)
// and the engine will wait that long before positioning the spotlight.
//
// Steps with a selector that doesn't resolve are filtered out at startup,
// so project-scoped steps are skipped gracefully when no project is active.
// -------------------------------------------------------------------------

// Helper used by section-scoped steps: ensures the named dashboard section
// is expanded so the spotlight target is actually visible. Returns 250ms
// when a transition is triggered so the engine can wait for the layout
// to settle before measuring the target.
function tourEnsureSectionOpen(key) {
  if (!state.collapsedSections) state.collapsedSections = {};
  if (state.collapsedSections[key]) {
    state.collapsedSections[key] = false;
    saveState();
    if (typeof applySectionStates === 'function') applySectionStates();
    return 250; // give the CSS transition + render a moment to settle
  }
  return 0;
}

